/* Cyber Dictionary — term data.
   Loaded as a plain script (not fetch) so the page also works from file://.
   Each entry: t = term, a = abbreviation or alias, d = domain, def = plain definition. */
window.DOMAINS = [
  "Networking & Protocols",
  "Cryptography",
  "Identity & Access",
  "Attacks & Exploitation",
  "Malware & Threat Actors",
  "Application Security",
  "Cloud & Infrastructure",
  "Endpoints & Systems",
  "Defense & Operations",
  "Governance, Risk & Compliance",
  "AI & Emerging Tech",
  "Dev & Delivery",
  "Compute & Hardware",
  "Intelligence & Investigations",
  "Classification & Personal Data"
];
window.TERMS = [
/* --- Networking & Protocols --- */
{t:"IP address",a:"Internet Protocol address",d:"Networking & Protocols",def:"The number that identifies a device on a network so traffic can be routed to it. IPv4 looks like 192.0.2.10; IPv6 is longer and hexadecimal."},
{t:"Subnet",a:"",d:"Networking & Protocols",def:"A slice of a larger network, carved out so that traffic inside it stays local and traffic leaving it has to pass a router. Written as a CIDR range like 10.0.1.0/24."},
{t:"CIDR",a:"Classless Inter-Domain Routing",d:"Networking & Protocols",def:"The /24-style notation for writing a block of IP addresses. The number after the slash says how many leading bits are fixed — the bigger the number, the smaller the block."},
{t:"NAT",a:"Network Address Translation",d:"Networking & Protocols",def:"A router rewriting private internal addresses into one public address on the way out. It is why a whole office can share a single IP, and why inbound connections need explicit port forwarding."},
{t:"Port",a:"",d:"Networking & Protocols",def:"A numbered door on a host. The IP gets you to the machine; the port gets you to the specific service — 22 for SSH, 443 for HTTPS."},
{t:"TCP",a:"Transmission Control Protocol",d:"Networking & Protocols",def:"The reliable transport: it sets up a connection, numbers every packet, and re-sends anything lost. Slower to start, but nothing arrives out of order."},
{t:"UDP",a:"User Datagram Protocol",d:"Networking & Protocols",def:"Fire-and-forget transport with no handshake and no re-sends. Used where speed beats completeness — DNS, video, games — and popular with attackers for spoofing and amplification."},
{t:"Three-way handshake",a:"SYN / SYN-ACK / ACK",d:"Networking & Protocols",def:"The three packets TCP exchanges to open a connection. Half-finished handshakes left open on purpose are the basis of the SYN flood attack."},
{t:"DNS",a:"Domain Name System",d:"Networking & Protocols",def:"The internet's phone book: it turns names like example.com into IP addresses. Almost every attack chain touches it, which is why DNS logs are gold for investigators."},
{t:"DNS resolver",a:"Recursive resolver",d:"Networking & Protocols",def:"The server that does the lookup legwork on your behalf, walking from the root servers down to the authoritative one and caching the answer."},
{t:"Authoritative name server",a:"",d:"Networking & Protocols",def:"The server that holds the real, official records for a domain. Everything else is a cached copy of what it said."},
{t:"DNSSEC",a:"DNS Security Extensions",d:"Networking & Protocols",def:"Cryptographic signatures on DNS records so a resolver can tell a genuine answer from a forged one. It proves authenticity, not confidentiality — the query is still visible."},
{t:"DoH / DoT",a:"DNS over HTTPS / DNS over TLS",d:"Networking & Protocols",def:"Encrypted DNS lookups. Good for user privacy, awkward for defenders, because it hides the query from the network monitoring that used to see it."},
{t:"DNS tunnelling",a:"",d:"Networking & Protocols",def:"Smuggling data in and out of a network inside DNS queries and responses. Slow, noisy if you look for it, and effective because DNS is rarely blocked."},
{t:"HTTP",a:"Hypertext Transfer Protocol",d:"Networking & Protocols",def:"The request-and-response protocol the web runs on. Plain HTTP is unencrypted, so anything sent over it can be read or altered in transit."},
{t:"HTTPS",a:"HTTP over TLS",d:"Networking & Protocols",def:"HTTP wrapped in TLS encryption. It proves you are talking to the site named in the certificate and stops anyone in the middle reading or editing the traffic."},
{t:"TLS",a:"Transport Layer Security",d:"Networking & Protocols",def:"The protocol that encrypts and authenticates most internet traffic. SSL is its dead predecessor — people still say SSL, but they mean TLS."},
{t:"TLS handshake",a:"",d:"Networking & Protocols",def:"The opening exchange where client and server agree a cipher, verify the certificate, and derive session keys before any real data moves."},
{t:"SNI",a:"Server Name Indication",d:"Networking & Protocols",def:"The field in a TLS handshake that names which site you want, sent before encryption starts. It leaks the hostname to anyone watching, which is what Encrypted Client Hello is meant to fix."},
{t:"mTLS",a:"Mutual TLS",d:"Networking & Protocols",def:"TLS where both sides present certificates, not just the server. Common between internal services because it authenticates the client without passwords."},
{t:"VPN",a:"Virtual Private Network",d:"Networking & Protocols",def:"An encrypted tunnel that makes a remote device behave as if it were on the internal network. It moves the trust boundary — it does not remove it."},
{t:"IPsec",a:"Internet Protocol Security",d:"Networking & Protocols",def:"A suite for encrypting and authenticating traffic at the IP layer, used for site-to-site VPNs. Works below the application, so apps need no changes."},
{t:"WireGuard",a:"",d:"Networking & Protocols",def:"A modern VPN protocol with a deliberately small codebase and a fixed set of modern ciphers. Faster and easier to audit than IPsec or OpenVPN."},
{t:"Proxy",a:"",d:"Networking & Protocols",def:"A middleman that makes requests on your behalf. A forward proxy fronts clients, a reverse proxy fronts servers, and both are natural places to inspect or filter traffic."},
{t:"Reverse proxy",a:"",d:"Networking & Protocols",def:"A server that sits in front of your applications, terminating TLS and passing requests inward. Where load balancing, caching, and web application firewalls usually live."},
{t:"Load balancer",a:"",d:"Networking & Protocols",def:"Spreads incoming traffic across several backend servers, and takes unhealthy ones out of rotation. Also a single point to enforce TLS and rate limits."},
{t:"Firewall",a:"",d:"Networking & Protocols",def:"A control that allows or blocks traffic by rule — usually address, port, and protocol. The traditional perimeter device, now also a per-host and per-cloud-resource control."},
{t:"NGFW",a:"Next-Generation Firewall",d:"Networking & Protocols",def:"A firewall that also identifies the application and user behind the traffic, not just ports and IPs, and can inspect decrypted sessions."},
{t:"IDS / IPS",a:"Intrusion Detection / Prevention System",d:"Networking & Protocols",def:"Sensors that watch traffic for known-bad patterns. An IDS alerts; an IPS sits inline and drops the traffic, which is more useful and more dangerous."},
{t:"Network segmentation",a:"",d:"Networking & Protocols",def:"Splitting a network into zones with controlled paths between them so a foothold in one zone does not reach everything. The single most effective limit on lateral movement."},
{t:"Microsegmentation",a:"",d:"Networking & Protocols",def:"Segmentation taken down to the individual workload, with policy attached to the service rather than the subnet. Usually enforced by agents or a service mesh."},
{t:"VLAN",a:"Virtual LAN",d:"Networking & Protocols",def:"A logical network laid over shared switch hardware, so two ports on the same switch can be on separate networks. A control, but a soft one — VLAN hopping is a real attack."},
{t:"ARP",a:"Address Resolution Protocol",d:"Networking & Protocols",def:"Maps IP addresses to hardware MAC addresses on a local network. It has no authentication at all, which is why ARP spoofing is trivial on a flat network."},
{t:"DHCP",a:"Dynamic Host Configuration Protocol",d:"Networking & Protocols",def:"Hands out IP addresses and network settings to devices as they join. A rogue DHCP server can quietly point every new device at an attacker's gateway and DNS."},
{t:"BGP",a:"Border Gateway Protocol",d:"Networking & Protocols",def:"How the internet's large networks tell each other which address ranges they can reach. Built on trust, so a bad or malicious announcement can hijack traffic globally."},
{t:"MAC address",a:"Media Access Control address",d:"Networking & Protocols",def:"The hardware identifier burned into a network interface. Useful for local identification, useless as an authenticator — it can be changed in one command."},
{t:"Packet capture",a:"PCAP",d:"Networking & Protocols",def:"A raw recording of network traffic, read with tools like Wireshark or tcpdump. The ground truth when logs disagree about what actually crossed the wire."},
{t:"NetFlow",a:"Flow data",d:"Networking & Protocols",def:"Summary records of who talked to whom, for how long, and how much — without the contents. Cheap to keep for a long time, which makes it the backbone of retrospective hunting."},
{t:"Air gap",a:"",d:"Networking & Protocols",def:"Physically isolating a system from other networks. Strong in principle, routinely defeated in practice by USB drives, maintenance laptops, and forgotten management links."},
/* --- Cryptography --- */
{t:"Plaintext / ciphertext",a:"",d:"Cryptography",def:"Plaintext is the readable data; ciphertext is what it looks like after encryption. Encryption turns one into the other, decryption turns it back."},
{t:"Symmetric encryption",a:"",d:"Cryptography",def:"One shared key both encrypts and decrypts. Fast, ideal for bulk data, but everyone who needs to read it needs the same secret — which is the hard part."},
{t:"Asymmetric encryption",a:"Public-key cryptography",d:"Cryptography",def:"A key pair: the public key encrypts or verifies, the private key decrypts or signs. Slower, but it lets strangers exchange secrets without meeting first."},
{t:"AES",a:"Advanced Encryption Standard",d:"Cryptography",def:"The default symmetric cipher, normally with 128- or 256-bit keys. Unbroken in practice — failures around it are nearly always key management or mode-of-operation mistakes."},
{t:"RSA",a:"Rivest–Shamir–Adleman",d:"Cryptography",def:"The classic public-key algorithm, based on the difficulty of factoring large numbers. Still common, but large and slow next to elliptic curve, and a prime target for quantum attacks."},
{t:"ECC",a:"Elliptic Curve Cryptography",d:"Cryptography",def:"Public-key cryptography over elliptic curves, giving the same strength as RSA with far smaller keys. The default for new TLS and signing work."},
{t:"Diffie–Hellman",a:"DH / ECDH",d:"Cryptography",def:"A method for two parties to agree a shared secret over a channel anyone can watch, without ever sending the secret itself."},
{t:"Forward secrecy",a:"PFS",d:"Cryptography",def:"Using fresh, throwaway keys per session so that stealing the long-term private key later does not decrypt traffic captured earlier."},
{t:"Hash function",a:"",d:"Cryptography",def:"A one-way function turning any input into a fixed-length fingerprint. Same input always gives the same digest; the digest cannot be reversed back to the input."},
{t:"SHA-256",a:"Secure Hash Algorithm 256",d:"Cryptography",def:"The workhorse hash for integrity checks, signatures, and blockchains. SHA-1 and MD5 are its broken predecessors and should never be used for security."},
{t:"Collision",a:"",d:"Cryptography",def:"Two different inputs producing the same hash. Once collisions are practical — as with MD5 and SHA-1 — the hash can no longer prove a file is unmodified."},
{t:"Salt",a:"",d:"Cryptography",def:"Random data added to a password before hashing, unique per user. It stops one precomputed table cracking every account at once."},
{t:"Pepper",a:"",d:"Cryptography",def:"A secret value mixed into password hashing and stored separately from the database, so a database dump alone is not enough to start cracking."},
{t:"Key derivation function",a:"KDF — bcrypt, scrypt, Argon2, PBKDF2",d:"Cryptography",def:"A deliberately slow, memory-hungry hash for passwords. Slowness is the feature: it makes brute-force guessing expensive."},
{t:"Rainbow table",a:"",d:"Cryptography",def:"A precomputed lookup from hashes back to passwords. Defeated entirely by per-user salting, which is why unsalted hashes are treated as plaintext."},
{t:"HMAC",a:"Hash-based Message Authentication Code",d:"Cryptography",def:"A hash keyed with a shared secret, proving both that a message is unaltered and that it came from someone holding the key."},
{t:"Digital signature",a:"",d:"Cryptography",def:"A hash of a message encrypted with the sender's private key. Anyone with the public key can confirm authorship and that nothing changed — and the signer cannot credibly deny it."},
{t:"Certificate",a:"X.509 certificate",d:"Cryptography",def:"A signed statement binding a public key to an identity such as a domain name. Trust rests entirely on trusting whoever signed it."},
{t:"Certificate authority",a:"CA",d:"Cryptography",def:"An organisation that issues and vouches for certificates. Its root certificate ships in browsers and operating systems, so a compromised CA breaks trust everywhere."},
{t:"PKI",a:"Public Key Infrastructure",d:"Cryptography",def:"The whole apparatus of issuing, distributing, renewing, and revoking certificates and keys. Most PKI incidents are expiries and misissuance, not cryptographic breaks."},
{t:"Certificate pinning",a:"",d:"Cryptography",def:"Hard-coding which certificate or key an app will accept, so a rogue CA cannot impersonate the server. Powerful, and easy to brick your own app with."},
{t:"CRL / OCSP",a:"Certificate Revocation List / Online Certificate Status Protocol",d:"Cryptography",def:"The two ways to check whether a certificate has been revoked early. Both are patchy in practice, which is why short-lived certificates are now preferred."},
{t:"Let's Encrypt / ACME",a:"Automatic Certificate Management Environment",d:"Cryptography",def:"A free CA and the protocol that automates issuing and renewing certificates. It made HTTPS the default rather than an upgrade."},
{t:"Encryption at rest",a:"",d:"Cryptography",def:"Data encrypted while stored on disk, so stolen hardware or a copied volume is useless. It does not protect data while the system is running and the key is loaded."},
{t:"Encryption in transit",a:"",d:"Cryptography",def:"Data encrypted while moving over a network. The pair to encryption at rest — most compliance regimes ask for both."},
{t:"End-to-end encryption",a:"E2EE",d:"Cryptography",def:"Only the sender and recipient hold the keys; the service carrying the message cannot read it. The distinction that matters when a provider is subpoenaed or breached."},
{t:"Key management",a:"KMS",d:"Cryptography",def:"Generating, storing, rotating, and retiring keys. Almost every real-world crypto failure is a key management failure, not a broken algorithm."},
{t:"HSM",a:"Hardware Security Module",d:"Cryptography",def:"A tamper-resistant device that generates and uses keys without ever exporting them. The key can be used but not copied, even by an administrator."},
{t:"TPM",a:"Trusted Platform Module",d:"Cryptography",def:"A small secure chip on a motherboard that stores keys and measures boot integrity. What full-disk encryption and secure boot lean on."},
{t:"Nonce / IV",a:"Number used once / Initialisation Vector",d:"Cryptography",def:"A unique value per encryption operation so identical plaintexts do not produce identical ciphertexts. Reusing one can collapse the security of the whole scheme."},
{t:"Entropy",a:"",d:"Cryptography",def:"Genuine unpredictability. Keys and tokens generated from weak entropy are guessable no matter how strong the algorithm."},
{t:"CSPRNG",a:"Cryptographically Secure Pseudo-Random Number Generator",d:"Cryptography",def:"A random source safe for keys and tokens. Ordinary language random() functions are not, and using one for a session token is a classic bug."},
{t:"Side-channel attack",a:"",d:"Cryptography",def:"Recovering secrets from physical or timing leakage rather than breaking the maths — power draw, execution time, cache behaviour, even sound."},
{t:"Constant-time comparison",a:"",d:"Cryptography",def:"Comparing secrets in a way that always takes the same time, so an attacker cannot learn the value one character at a time from response timing."},
{t:"Post-quantum cryptography",a:"PQC",d:"Cryptography",def:"Algorithms designed to survive quantum computers, now standardised as ML-KEM and ML-DSA. Being adopted early because encrypted traffic stolen today could be decrypted later."},
{t:"Harvest now, decrypt later",a:"",d:"Cryptography",def:"Recording encrypted traffic today in the expectation of breaking it with future technology. The reason long-lived secrets need post-quantum protection now, not eventually."},
{t:"Homomorphic encryption",a:"",d:"Cryptography",def:"Computing directly on encrypted data without decrypting it. Real, but still slow enough that it is used narrowly rather than by default."},
{t:"Steganography",a:"",d:"Cryptography",def:"Hiding a message inside something innocuous, such as an image, so nobody knows a message exists. Concealment rather than encryption — often used to smuggle payloads past filters."},
/* --- Identity & Access --- */
{t:"Authentication",a:"AuthN",d:"Identity & Access",def:"Proving who you are. Distinct from authorisation, and confusing the two is the root of a surprising number of vulnerabilities."},
{t:"Authorisation",a:"AuthZ",d:"Identity & Access",def:"Deciding what an already-identified user is allowed to do. A logged-in user reaching another user's record is an authorisation failure, not an authentication one."},
{t:"Multi-factor authentication",a:"MFA / 2FA",d:"Identity & Access",def:"Requiring two or more different kinds of proof — something you know, have, or are. The single highest-value control against stolen passwords."},
{t:"TOTP",a:"Time-based One-Time Password",d:"Identity & Access",def:"The rotating six-digit code from an authenticator app. Far better than SMS, but still phishable, because the user can be tricked into typing it into a fake site."},
{t:"Phishing-resistant MFA",a:"",d:"Identity & Access",def:"Factors bound to the real domain so they cannot be relayed to a fake one — hardware security keys and passkeys. Codes and push prompts are not phishing-resistant."},
{t:"FIDO2 / WebAuthn",a:"",d:"Identity & Access",def:"The open standards behind hardware keys and passkeys. The browser signs a challenge with a key tied to the exact origin, so a lookalike site gets nothing."},
{t:"Passkey",a:"",d:"Identity & Access",def:"A WebAuthn credential stored on a device or synced through a platform account, replacing the password entirely. Unlocked with a fingerprint, face, or PIN."},
{t:"Security key",a:"Hardware token, YubiKey",d:"Identity & Access",def:"A physical device that holds authentication keys and requires a touch to use. The strongest widely-available second factor."},
{t:"SSO",a:"Single Sign-On",d:"Identity & Access",def:"One login granting access to many applications. It centralises control and logging — and centralises risk, since the identity provider becomes the crown jewel."},
{t:"IdP",a:"Identity Provider",d:"Identity & Access",def:"The system that authenticates users and vouches for them to applications — Entra ID, Okta, Google Workspace. Compromise it and every downstream app follows."},
{t:"SAML",a:"Security Assertion Markup Language",d:"Identity & Access",def:"The older XML-based standard for federated SSO, still standard in enterprise software. Its signature handling has a long history of bypass bugs."},
{t:"OAuth 2.0",a:"",d:"Identity & Access",def:"A delegation framework: it lets an app act on your behalf against another service without ever seeing your password. It is about access, not identity."},
{t:"OIDC",a:"OpenID Connect",d:"Identity & Access",def:"An identity layer built on top of OAuth 2.0. OAuth grants access; OIDC actually tells the app who you are, in a signed ID token."},
{t:"JWT",a:"JSON Web Token",d:"Identity & Access",def:"A signed, self-describing token carrying claims about a user. Readable by anyone holding it — signed, not secret — so never put anything confidential inside."},
{t:"Bearer token",a:"",d:"Identity & Access",def:"A credential where possession alone grants access, with no further proof required. Which is exactly why leaked tokens in logs or repos are so damaging."},
{t:"Session hijacking",a:"",d:"Identity & Access",def:"Stealing a valid session cookie or token to become an already-authenticated user, skipping login and MFA entirely. Infostealer malware's main product."},
{t:"Token binding / DPoP",a:"",d:"Identity & Access",def:"Tying a token to the client that requested it, so a stolen token is useless elsewhere. The countermeasure to plain bearer tokens."},
{t:"RBAC",a:"Role-Based Access Control",d:"Identity & Access",def:"Permissions attached to roles, and roles attached to people. Simple and auditable, until the roles multiply and everyone ends up in several."},
{t:"ABAC",a:"Attribute-Based Access Control",d:"Identity & Access",def:"Access decided by attributes — department, device posture, location, time — evaluated as policy. More expressive than roles, and harder to reason about."},
{t:"Least privilege",a:"",d:"Identity & Access",def:"Give each account only the access its job requires, and no more. The principle nearly every access review is trying to enforce."},
{t:"Privilege escalation",a:"",d:"Identity & Access",def:"Gaining rights beyond those granted. Vertical means user to admin; horizontal means reaching another user's data at the same level."},
{t:"PAM",a:"Privileged Access Management",d:"Identity & Access",def:"Controls specifically for admin accounts — vaulted credentials, checkout with approval, session recording, and automatic rotation."},
{t:"Just-in-time access",a:"JIT",d:"Identity & Access",def:"Granting elevated rights only for a defined window, then removing them automatically. Replaces standing admin access, which is what attackers actually hunt for."},
{t:"Service account",a:"Machine identity",d:"Identity & Access",def:"A non-human account used by an application or script. Typically over-permissioned, rarely rotated, never MFA-protected — a standing favourite for attackers."},
{t:"Workload identity",a:"",d:"Identity & Access",def:"Giving a running service a short-lived, automatically issued identity instead of a static key. The modern replacement for hard-coded credentials."},
{t:"Federation",a:"",d:"Identity & Access",def:"Trusting another organisation's identity provider so their users can access your systems without separate accounts. Convenient, and it exports your trust decision."},
{t:"Directory service",a:"Active Directory, LDAP",d:"Identity & Access",def:"The central store of users, groups, and computers. In most enterprises, compromising Active Directory is functionally the same as compromising everything."},
{t:"Kerberos",a:"",d:"Identity & Access",def:"The ticket-based authentication protocol underneath Windows domains. Its ticket mechanics give rise to Kerberoasting, Golden Ticket, and Silver Ticket attacks."},
{t:"Pass-the-hash",a:"PtH",d:"Identity & Access",def:"Authenticating with a stolen password hash without ever cracking it, because the protocol accepts the hash as proof."},
{t:"Kerberoasting",a:"",d:"Identity & Access",def:"Requesting service tickets for accounts with weak passwords and cracking them offline. Quiet, effective, and needs only an ordinary domain account to start."},
{t:"Golden Ticket",a:"",d:"Identity & Access",def:"Forging Kerberos tickets using the domain's krbtgt key, granting an attacker persistent, self-issued access to anything in the domain."},
{t:"Credential stuffing",a:"",d:"Identity & Access",def:"Replaying username and password pairs from earlier breaches against other sites, betting on reuse. Cheap, automated, and depressingly effective."},
{t:"Password spraying",a:"",d:"Identity & Access",def:"Trying one or two common passwords across many accounts, staying under lockout thresholds. Slower than brute force and far less likely to trip alarms."},
{t:"Account takeover",a:"ATO",d:"Identity & Access",def:"An attacker gaining full control of a legitimate account, then using its normal permissions. Hard to spot precisely because nothing technically breaks."},
{t:"Identity lifecycle",a:"Joiner–Mover–Leaver",d:"Identity & Access",def:"Provisioning access on hire, adjusting it on transfer, and removing it on exit. Leaver failures — dormant accounts with live access — are a recurring audit finding."},
{t:"SCIM",a:"System for Cross-domain Identity Management",d:"Identity & Access",def:"The standard for pushing user creation, updates, and deprovisioning from an identity provider into applications automatically."},
{t:"Access review",a:"Recertification / attestation",d:"Identity & Access",def:"A periodic check where owners confirm who still needs access. The main defence against privilege creep — and often rubber-stamped."},
{t:"Zero trust",a:"",d:"Identity & Access",def:"Assume no network location is trusted; verify identity, device, and context on every request. A design principle, not a product, whatever a vendor tells you."},
/* --- Attacks & Exploitation --- */
{t:"Threat / vulnerability / risk",a:"",d:"Attacks & Exploitation",def:"A threat is who might hurt you, a vulnerability is the weakness they would use, and risk is the combination weighted by likelihood and impact. Vendors blur these constantly."},
{t:"Attack surface",a:"",d:"Attacks & Exploitation",def:"Everything an attacker could touch — exposed services, endpoints, APIs, staff, suppliers. Reducing it is usually cheaper than defending it."},
{t:"Exploit",a:"",d:"Attacks & Exploitation",def:"Working code or a technique that turns a vulnerability into actual unauthorised behaviour. A vulnerability is theoretical until an exploit exists."},
{t:"Payload",a:"",d:"Attacks & Exploitation",def:"The part of an attack that does the intended damage or gives access, as opposed to the delivery mechanism that gets it there."},
{t:"Zero-day",a:"0-day",d:"Attacks & Exploitation",def:"A vulnerability being exploited before a patch exists. Rare and expensive — most breaches still use flaws patched months earlier."},
{t:"N-day",a:"One-day",d:"Attacks & Exploitation",def:"A known, patched vulnerability that is still exploitable because the target has not applied the fix. The overwhelming majority of real intrusions."},
{t:"Proof of concept",a:"PoC",d:"Attacks & Exploitation",def:"Minimal code demonstrating that a vulnerability is genuinely exploitable. Public PoC release usually marks the start of mass scanning."},
{t:"Phishing",a:"",d:"Attacks & Exploitation",def:"A fraudulent message designed to make someone hand over credentials or run something. Still the most common way intrusions begin."},
{t:"Spear phishing",a:"",d:"Attacks & Exploitation",def:"Phishing tailored to one person using real details about their role, colleagues, or current projects. Much higher success rate, much lower volume."},
{t:"Whaling",a:"",d:"Attacks & Exploitation",def:"Spear phishing aimed at executives, whose approval authority and access make a single success unusually valuable."},
{t:"BEC",a:"Business Email Compromise",d:"Attacks & Exploitation",def:"Impersonating or hijacking a trusted business mailbox to redirect a payment or an invoice. Consistently causes larger financial losses than ransomware."},
{t:"Smishing / vishing",a:"",d:"Attacks & Exploitation",def:"Phishing by SMS and by voice call. Voice versions increasingly use cloned audio, and helpdesk vishing is a proven route past MFA."},
{t:"Social engineering",a:"",d:"Attacks & Exploitation",def:"Manipulating people rather than systems — urgency, authority, helpfulness. It bypasses technical controls by using someone who already holds legitimate access."},
{t:"Pretexting",a:"",d:"Attacks & Exploitation",def:"Inventing a plausible scenario and identity to justify an unusual request. The setup that makes the eventual ask feel routine."},
{t:"MFA fatigue",a:"Push bombing",d:"Attacks & Exploitation",def:"Spamming approval prompts until a tired user taps accept. Countered with number matching or by dropping push approval altogether."},
{t:"Adversary-in-the-middle",a:"AiTM / MitM",d:"Attacks & Exploitation",def:"Sitting between the user and the real site, relaying traffic and capturing the session cookie after login. It defeats codes and push, but not hardware-bound factors."},
{t:"SIM swapping",a:"",d:"Attacks & Exploitation",def:"Convincing a mobile carrier to move a number to an attacker's SIM, capturing every SMS code. The reason SMS is the weakest second factor."},
{t:"Watering hole",a:"",d:"Attacks & Exploitation",def:"Compromising a site the intended victims already visit and waiting for them to arrive. No message to the target means nothing to flag as suspicious."},
{t:"Drive-by download",a:"",d:"Attacks & Exploitation",def:"Malware installed simply by loading a page, exploiting the browser or a plugin without any click."},
{t:"Malvertising",a:"",d:"Attacks & Exploitation",def:"Malicious code delivered through legitimate ad networks, so a trusted site serves it unknowingly."},
{t:"Typosquatting",a:"",d:"Attacks & Exploitation",def:"Registering near-miss domains or package names to catch typos. Used both for phishing and for poisoning software dependencies."},
{t:"Brute force",a:"",d:"Attacks & Exploitation",def:"Trying every possibility until something works. Defeated by rate limiting, lockouts, and enough entropy to make the search space impractical."},
{t:"DoS / DDoS",a:"(Distributed) Denial of Service",d:"Attacks & Exploitation",def:"Overwhelming a service so real users cannot reach it. Distributed versions use many hosts at once, often a botnet or reflected traffic."},
{t:"Amplification attack",a:"Reflection",d:"Attacks & Exploitation",def:"Sending small spoofed requests to services that reply with much larger responses, aimed at the victim. DNS and NTP are classic amplifiers."},
{t:"Botnet",a:"",d:"Attacks & Exploitation",def:"A fleet of compromised machines under one controller, rented out for denial of service, spam, proxying, or credential stuffing."},
{t:"Command and control",a:"C2 / C&C",d:"Attacks & Exploitation",def:"The channel an attacker uses to issue instructions to compromised hosts. Increasingly hidden inside normal cloud and messaging traffic."},
{t:"Beaconing",a:"",d:"Attacks & Exploitation",def:"An implant checking in with its controller at regular intervals. The rhythm of those check-ins is one of the most reliable detections available."},
{t:"Lateral movement",a:"",d:"Attacks & Exploitation",def:"Moving from the first compromised host to more valuable ones inside the network. Usually done with stolen valid credentials, not new exploits."},
{t:"Persistence",a:"",d:"Attacks & Exploitation",def:"Making access survive reboots, password resets, and cleanup — scheduled tasks, services, registry keys, rogue OAuth grants, extra SSH keys."},
{t:"Exfiltration",a:"",d:"Attacks & Exploitation",def:"Getting stolen data out, often in small encrypted chunks over allowed channels like HTTPS or a sanctioned file-sharing service."},
{t:"Living off the land",a:"LOLBins",d:"Attacks & Exploitation",def:"Using tools already installed — PowerShell, certutil, curl, WMI — instead of dropping malware. Nothing to detect as a bad file, so behaviour is the only signal."},
{t:"Fileless attack",a:"",d:"Attacks & Exploitation",def:"Malicious activity running in memory or scripting engines without writing to disk. Invisible to file-scanning antivirus by design."},
{t:"Supply chain attack",a:"",d:"Attacks & Exploitation",def:"Compromising a supplier, library, or update channel to reach everyone downstream. One breach, many victims — SolarWinds and XZ Utils are the canonical cases."},
{t:"Dependency confusion",a:"",d:"Attacks & Exploitation",def:"Publishing a public package with the same name as a company's internal one so build tools fetch the attacker's version by mistake."},
{t:"Insider threat",a:"",d:"Attacks & Exploitation",def:"Harm caused by someone with legitimate access — malicious, negligent, or coerced. Technical controls help least here; process and monitoring matter most."},
{t:"Shadow IT",a:"",d:"Attacks & Exploitation",def:"Tools and accounts staff adopt without approval. Not hostile, but invisible to security, unpatched, and outside the incident response plan."},
{t:"Initial access broker",a:"IAB",d:"Attacks & Exploitation",def:"A criminal specialising in breaking in and selling that foothold on. The reason ransomware crews can skip the intrusion step entirely."},
{t:"Attack chain",a:"Kill chain",d:"Attacks & Exploitation",def:"The ordered stages of an intrusion, from reconnaissance through to impact. Useful because breaking any single link stops the whole chain."},
/* --- Malware & Threat Actors --- */
{t:"Malware",a:"",d:"Malware & Threat Actors",def:"Any software written to do harm or gain unauthorised access. An umbrella term covering everything below it."},
{t:"Virus",a:"",d:"Malware & Threat Actors",def:"Malicious code that attaches itself to a file or program and spreads when that host is run. Largely historical, but the word stuck to everything."},
{t:"Worm",a:"",d:"Malware & Threat Actors",def:"Malware that spreads by itself across a network with no user action. Why unpatched internet-facing services are treated as emergencies."},
{t:"Trojan",a:"",d:"Malware & Threat Actors",def:"Malware disguised as something wanted — a cracked app, an installer, a document viewer. It relies on the user choosing to run it."},
{t:"Ransomware",a:"",d:"Malware & Threat Actors",def:"Malware that encrypts data and demands payment for the key. Modern operations steal the data first, so paying does not undo the breach."},
{t:"Double extortion",a:"",d:"Malware & Threat Actors",def:"Encrypting data and also threatening to publish it. Backups solve the outage but not the leak, which is why they are no longer a complete answer."},
{t:"Ransomware-as-a-service",a:"RaaS",d:"Malware & Threat Actors",def:"A criminal business model where developers rent their malware and infrastructure to affiliates for a cut. It industrialised ransomware."},
{t:"Wiper",a:"",d:"Malware & Threat Actors",def:"Malware built purely to destroy data, sometimes disguised as ransomware. There is no key, because recovery was never the point."},
{t:"Spyware",a:"",d:"Malware & Threat Actors",def:"Software that covertly monitors activity — messages, location, microphone, camera. Includes commercial surveillance tools sold to states."},
{t:"Stalkerware",a:"",d:"Malware & Threat Actors",def:"Consumer spyware marketed for monitoring partners, children, or staff. Legally grey, technically ordinary, and a serious safety issue in domestic abuse."},
{t:"Keylogger",a:"",d:"Malware & Threat Actors",def:"Records keystrokes to capture passwords and messages. Exists as software and as small hardware devices inline with a keyboard."},
{t:"Infostealer",a:"Stealer",d:"Malware & Threat Actors",def:"Malware that grabs saved passwords, cookies, and session tokens, then leaves. Its output feeds credential markets and skips MFA via stolen sessions."},
{t:"Rootkit",a:"",d:"Malware & Threat Actors",def:"Malware that hides itself deep in the operating system or below it, altering what the system reports about itself. Often only detectable from outside the host."},
{t:"Bootkit",a:"",d:"Malware & Threat Actors",def:"A rootkit that loads before the operating system, surviving reinstalls. Secure Boot and measured boot exist mainly to stop this."},
{t:"Backdoor",a:"",d:"Malware & Threat Actors",def:"A hidden way back into a system that bypasses normal authentication. Left by attackers, and occasionally by developers who meant it as a debug feature."},
{t:"RAT",a:"Remote Access Trojan",d:"Malware & Threat Actors",def:"Malware giving an attacker interactive control of a machine — files, screen, camera, shell — as if sitting at it."},
{t:"Loader / dropper",a:"",d:"Malware & Threat Actors",def:"Small first-stage malware whose only job is to fetch and run the real payload. Kept simple so it stays undetected."},
{t:"Cryptominer",a:"Cryptojacking",d:"Malware & Threat Actors",def:"Malware that quietly uses your compute to mine cryptocurrency. Low drama, but it signals that something else could have run instead."},
{t:"Adware",a:"",d:"Malware & Threat Actors",def:"Software that injects ads or hijacks searches. Mostly a nuisance, sometimes a delivery route for worse."},
{t:"Scareware",a:"",d:"Malware & Threat Actors",def:"Fake alerts claiming infection to push a purchase or a phone call. The on-ramp to tech-support fraud."},
{t:"Packer / crypter",a:"",d:"Malware & Threat Actors",def:"Tools that compress or encrypt malware so its file signature changes. Cheap evasion, which is why signature-only detection fails."},
{t:"Polymorphic malware",a:"",d:"Malware & Threat Actors",def:"Malware that rewrites its own code each time it spreads, so no two copies look alike to a scanner."},
{t:"Obfuscation",a:"",d:"Malware & Threat Actors",def:"Deliberately making code hard to read or analyse. Used by malware authors and, legitimately, by software vendors protecting their products."},
{t:"Sandbox evasion",a:"",d:"Malware & Threat Actors",def:"Malware checking whether it is being watched — virtual machine artefacts, no mouse movement, too little uptime — and staying dormant if so."},
{t:"Logic bomb",a:"",d:"Malware & Threat Actors",def:"Malicious code that triggers on a condition, such as a date or a name disappearing from payroll. Usually an insider's tool."},
{t:"Threat actor",a:"",d:"Malware & Threat Actors",def:"The person or group behind an attack. Grouped by capability and motive rather than by the tools they happen to use."},
{t:"APT",a:"Advanced Persistent Threat",d:"Malware & Threat Actors",def:"A well-resourced group, usually state-linked, that gets in and stays quietly for a long time. Persistence and patience matter more than sophistication."},
{t:"Hacktivist",a:"",d:"Malware & Threat Actors",def:"An attacker motivated by a political or social cause rather than money. Typically defacement, leaks, or denial of service."},
{t:"Script kiddie",a:"",d:"Malware & Threat Actors",def:"Someone using others' tools without understanding them. Still capable of real damage against anything left unpatched."},
{t:"Red team / blue team",a:"",d:"Malware & Threat Actors",def:"Red attacks to test defences, blue defends and detects. Purple team is the practice of running both together so findings actually improve detection."},
{t:"Threat intelligence",a:"CTI",d:"Malware & Threat Actors",def:"Analysed information about who is attacking, how, and what to look for. Useful only when it changes a decision, not when it is a feed nobody reads."},
{t:"IOC",a:"Indicator of Compromise",d:"Malware & Threat Actors",def:"An observable sign of intrusion — a hash, a domain, an IP. Easy to share, easy for attackers to change, so it dates quickly."},
{t:"TTPs",a:"Tactics, Techniques, and Procedures",d:"Malware & Threat Actors",def:"How a group operates rather than what they used once. Far more durable than indicators, and the basis of ATT&CK-style detection."},
{t:"Pyramid of Pain",a:"",d:"Malware & Threat Actors",def:"A model ranking indicators by how much it costs an attacker when you block them. Hashes are trivial to change; behaviours are not."},
{t:"MITRE ATT&CK",a:"",d:"Malware & Threat Actors",def:"A public catalogue of real-world attacker techniques, organised by tactic. The common vocabulary for describing and mapping detection coverage."},
{t:"Attribution",a:"",d:"Malware & Threat Actors",def:"Assigning an attack to a specific actor. Genuinely hard, often political, and rarely changes what a defender should do next."},
{t:"Malware family",a:"",d:"Malware & Threat Actors",def:"A cluster of related samples sharing code and behaviour. Naming is inconsistent across vendors, which is why the same thing has five names."},
{t:"Dwell time",a:"",d:"Malware & Threat Actors",def:"How long an intruder is inside before being detected. The metric that best reflects whether detection actually works."},
/* --- Application Security --- */
{t:"OWASP",a:"Open Worldwide Application Security Project",d:"Application Security",def:"A nonprofit producing free application security guidance, tools, and the widely-cited Top 10 lists."},
{t:"OWASP Top 10",a:"",d:"Application Security",def:"A periodically-updated list of the most critical web application risks. An awareness document, not a checklist to certify against."},
{t:"Injection",a:"",d:"Application Security",def:"Untrusted input being interpreted as code or commands. The root cause behind SQL injection, command injection, and most template attacks."},
{t:"SQL injection",a:"SQLi",d:"Application Security",def:"Slipping SQL into input so the database runs it. Fixed properly by parameterised queries — never by filtering quotes."},
{t:"XSS",a:"Cross-Site Scripting",d:"Application Security",def:"Injecting JavaScript that runs in another user's browser under your site's origin, letting an attacker read cookies or act as that user."},
{t:"Stored vs reflected XSS",a:"",d:"Application Security",def:"Stored XSS is saved server-side and hits every viewer; reflected XSS is echoed back from a crafted link and hits whoever clicks it."},
{t:"DOM-based XSS",a:"",d:"Application Security",def:"XSS caused entirely by client-side JavaScript writing untrusted data into the page. The server may never see the payload at all."},
{t:"CSRF",a:"Cross-Site Request Forgery",d:"Application Security",def:"Tricking a logged-in browser into sending a state-changing request the user never intended. Blocked with anti-CSRF tokens and SameSite cookies."},
{t:"SSRF",a:"Server-Side Request Forgery",d:"Application Security",def:"Making the server fetch a URL of the attacker's choosing, often reaching internal services or cloud metadata endpoints the internet cannot."},
{t:"IDOR",a:"Insecure Direct Object Reference",d:"Application Security",def:"Changing an identifier in a URL or request and getting someone else's data because the server never checked ownership."},
{t:"Broken access control",a:"",d:"Application Security",def:"Authorisation not enforced consistently on the server. Persistently the number one web risk, because it cannot be found by scanners alone."},
{t:"Path traversal",a:"Directory traversal",d:"Application Security",def:"Using ../ sequences to read files outside the intended directory, such as configuration or key material."},
{t:"Command injection",a:"",d:"Application Security",def:"User input reaching a shell command, letting an attacker run arbitrary system commands as the application's user."},
{t:"Deserialisation vulnerability",a:"",d:"Application Security",def:"Rebuilding objects from untrusted serialised data, which in many languages can trigger code execution during reconstruction."},
{t:"XXE",a:"XML External Entity",d:"Application Security",def:"Abusing XML parsers that resolve external references, allowing file reads or server-side requests. Fixed by disabling external entities."},
{t:"Race condition",a:"TOCTOU",d:"Application Security",def:"A bug where the outcome depends on timing between a check and its use. Exploited by firing simultaneous requests — a common cause of duplicate refunds and coupon abuse."},
{t:"Buffer overflow",a:"",d:"Application Security",def:"Writing past the end of a memory buffer, corrupting adjacent data and often enabling code execution. Mostly a C and C++ problem."},
{t:"Use-after-free",a:"",d:"Application Security",def:"Using memory after it has been released, letting an attacker control what now sits there. A leading source of browser and kernel exploits."},
{t:"Memory safety",a:"",d:"Application Security",def:"Preventing whole classes of memory bugs by design. The main argument for Rust, Go, and similar languages in new systems code."},
{t:"Input validation",a:"",d:"Application Security",def:"Checking that input matches an expected shape before use. Allow-lists work; deny-lists of bad characters eventually fail."},
{t:"Output encoding",a:"",d:"Application Security",def:"Escaping data for the context it lands in — HTML, attribute, JavaScript, SQL. The correct fix for XSS, applied at the point of output."},
{t:"Parameterised query",a:"Prepared statement",d:"Application Security",def:"Sending SQL structure and data separately so input can never become code. The definitive SQL injection fix."},
{t:"CSP",a:"Content Security Policy",d:"Application Security",def:"A header telling the browser which sources of script, style, and frames are allowed. A strong second line of defence when XSS slips through."},
{t:"CORS",a:"Cross-Origin Resource Sharing",d:"Application Security",def:"Rules for when one origin may read another's responses. Loosening it to a wildcard with credentials is a routine and serious misconfiguration."},
{t:"Same-origin policy",a:"SOP",d:"Application Security",def:"The browser rule that keeps one site's scripts from reading another site's data. The foundation everything else in web security sits on."},
{t:"Secure cookie flags",a:"HttpOnly, Secure, SameSite",d:"Application Security",def:"HttpOnly hides a cookie from JavaScript, Secure restricts it to HTTPS, and SameSite limits cross-site sending. Three flags, most cookie attacks covered."},
{t:"HSTS",a:"HTTP Strict Transport Security",d:"Application Security",def:"A header telling browsers to only ever use HTTPS for a domain, removing the downgrade window on first navigation."},
{t:"Subresource integrity",a:"SRI",d:"Application Security",def:"A hash on a third-party script tag so the browser refuses it if the file changed. Cheap protection against a compromised CDN."},
{t:"SAST",a:"Static Application Security Testing",d:"Application Security",def:"Scanning source code for vulnerable patterns without running it. Broad coverage, high false-positive rate."},
{t:"DAST",a:"Dynamic Application Security Testing",d:"Application Security",def:"Testing a running application from the outside. Fewer false positives, but it only finds what it can reach."},
{t:"SCA",a:"Software Composition Analysis",d:"Application Security",def:"Inventorying third-party dependencies and flagging known-vulnerable versions. Most of a modern codebase is not written in-house."},
{t:"Fuzzing",a:"",d:"Application Security",def:"Throwing malformed and random input at a program to find crashes. Extremely effective at finding memory-safety and parser bugs."},
{t:"Penetration test",a:"Pentest",d:"Application Security",def:"An authorised, time-boxed attempt to break in and prove impact. Deeper than a scan, narrower than a red team engagement."},
{t:"Bug bounty",a:"",d:"Application Security",def:"Paying external researchers for valid vulnerability reports. Continuous and broad, but no substitute for internal testing."},
{t:"Responsible disclosure",a:"Coordinated disclosure",d:"Application Security",def:"Reporting a flaw privately and agreeing a window before publication, so a fix exists before the details do."},
{t:"Secure SDLC",a:"",d:"Application Security",def:"Building security into every stage of development rather than testing at the end. Threat modelling, review, testing, and monitoring as normal practice."},
{t:"Threat modelling",a:"STRIDE",d:"Application Security",def:"Working out systematically what could go wrong with a design before it is built. Cheapest security work there is, and the most often skipped."},
{t:"Shift left",a:"",d:"Application Security",def:"Moving security checks earlier into design and development. Genuinely valuable, and frequently reduced to adding a scanner to the build."},
{t:"Secrets management",a:"",d:"Application Security",def:"Keeping credentials out of code and configuration and in a vault with rotation and audit. Hard-coded secrets in repositories remain a top breach cause."},
{t:"Hard-coded credentials",a:"",d:"Application Security",def:"Passwords or keys written directly into source. They spread through forks, logs, and backups, and cannot be rotated without a code change."},
/* --- Cloud & Infrastructure --- */
{t:"IaaS / PaaS / SaaS",a:"",d:"Cloud & Infrastructure",def:"Three levels of cloud service — raw machines, a managed platform, or finished software. The level decides how much security is yours and how much is the provider's."},
{t:"Shared responsibility model",a:"",d:"Cloud & Infrastructure",def:"The provider secures the cloud; you secure what you put in it. Nearly every cloud breach lands on the customer's side of that line."},
{t:"Public / private / hybrid cloud",a:"",d:"Cloud & Infrastructure",def:"Shared provider infrastructure, dedicated infrastructure, or a mix. Hybrid is the common reality, and the seams between the two are where control gaps live."},
{t:"Multi-cloud",a:"",d:"Cloud & Infrastructure",def:"Using more than one cloud provider. Reduces lock-in, multiplies the number of identity and policy models you must get right."},
{t:"Region / availability zone",a:"",d:"Cloud & Infrastructure",def:"A geographic location and an isolated datacentre within it. Regions matter for data residency law; zones matter for surviving hardware failure."},
{t:"Virtual machine",a:"VM",d:"Cloud & Infrastructure",def:"A simulated computer running on shared hardware, with its own operating system. Strong isolation, heavier than a container."},
{t:"Hypervisor",a:"",d:"Cloud & Infrastructure",def:"The layer that runs and isolates virtual machines. Escaping it is the most valuable cloud vulnerability class, and correspondingly rare."},
{t:"Container",a:"Docker",d:"Cloud & Infrastructure",def:"An application packaged with its dependencies, sharing the host kernel. Fast and portable, but isolation is weaker than a VM's."},
{t:"Container image",a:"",d:"Cloud & Infrastructure",def:"The read-only template a container starts from. Base images carry their own vulnerabilities, so scanning and rebuilding matter as much as your code."},
{t:"Container escape",a:"",d:"Cloud & Infrastructure",def:"Breaking out of a container to the host. Usually the result of privileged mode, a mounted socket, or an unpatched kernel."},
{t:"Kubernetes",a:"K8s",d:"Cloud & Infrastructure",def:"The dominant container orchestrator. Powerful, and insecure by default in ways that need deliberate configuration to fix."},
{t:"Pod",a:"",d:"Cloud & Infrastructure",def:"Kubernetes' smallest deployable unit — one or more containers sharing a network identity and storage."},
{t:"Service mesh",a:"Istio, Linkerd",d:"Cloud & Infrastructure",def:"A layer that handles service-to-service traffic, giving mutual TLS, policy, and telemetry without changing application code."},
{t:"Serverless",a:"FaaS, Lambda",d:"Cloud & Infrastructure",def:"Running functions without managing servers. No host to patch, but function permissions and event sources become the security surface."},
{t:"Infrastructure as code",a:"IaC — Terraform, CloudFormation",d:"Cloud & Infrastructure",def:"Defining infrastructure in version-controlled files. Makes environments reviewable and repeatable — and replicates a mistake everywhere instantly."},
{t:"Immutable infrastructure",a:"",d:"Cloud & Infrastructure",def:"Replacing servers instead of patching them in place. Removes configuration drift and quietly destroys most attacker persistence."},
{t:"Configuration drift",a:"",d:"Cloud & Infrastructure",def:"Live systems gradually diverging from their defined state through manual fixes. The reason a system that passed audit fails six months later."},
{t:"CSPM",a:"Cloud Security Posture Management",d:"Cloud & Infrastructure",def:"Continuously checking cloud configuration against policy — public buckets, open groups, missing encryption, over-broad roles."},
{t:"CWPP / CNAPP",a:"Cloud Workload / Native Application Protection Platform",d:"Cloud & Infrastructure",def:"Runtime protection for cloud workloads, and the bundled platforms that combine posture, workload, and identity checks."},
{t:"CIEM",a:"Cloud Infrastructure Entitlement Management",d:"Cloud & Infrastructure",def:"Finding and trimming excessive cloud permissions. Most cloud identities hold far more rights than they ever use."},
{t:"IAM policy",a:"",d:"Cloud & Infrastructure",def:"The rules defining which identity may perform which action on which cloud resource. Wildcards in these are the most common cloud misconfiguration."},
{t:"Instance metadata service",a:"IMDS",d:"Cloud & Infrastructure",def:"A local endpoint that hands running instances their cloud credentials. Reachable via SSRF unless the hardened version is enforced."},
{t:"Security group",a:"Network ACL",d:"Cloud & Infrastructure",def:"Cloud firewall rules attached to resources or subnets. An accidentally open management port here is a recurring breach origin."},
{t:"Object storage",a:"S3, Blob, GCS",d:"Cloud & Infrastructure",def:"Cloud file storage addressed by key rather than path. Publicly-readable buckets remain one of the most common data exposures."},
{t:"Bastion host",a:"Jump box",d:"Cloud & Infrastructure",def:"A single hardened, monitored entry point for administrative access to a private network, so nothing else needs exposing."},
{t:"Backup",a:"",d:"Cloud & Infrastructure",def:"A separate copy of data that can be restored. Untested backups are a plan, not a control — and ransomware crews delete the ones they can reach."},
{t:"3-2-1 rule",a:"",d:"Cloud & Infrastructure",def:"Three copies of data, on two media types, with one off-site. Modern versions add one offline or immutable copy."},
{t:"Immutable backup",a:"WORM",d:"Cloud & Infrastructure",def:"Backups that cannot be altered or deleted for a set period, even by an administrator. The specific answer to ransomware deleting backups."},
{t:"RTO / RPO",a:"Recovery Time / Point Objective",d:"Cloud & Infrastructure",def:"How fast you must be back, and how much data you can afford to lose. Two numbers that decide the entire backup architecture."},
{t:"Disaster recovery",a:"DR",d:"Cloud & Infrastructure",def:"Restoring technology after a major failure. Distinct from business continuity, which covers how the organisation keeps operating meanwhile."},
{t:"High availability",a:"HA",d:"Cloud & Infrastructure",def:"Design that survives component failure without downtime, through redundancy and failover. Availability is a security property too."},
{t:"CDN",a:"Content Delivery Network",d:"Cloud & Infrastructure",def:"Distributed edge servers caching content close to users. Also a practical place to absorb denial-of-service traffic and enforce WAF rules."},
{t:"WAF",a:"Web Application Firewall",d:"Cloud & Infrastructure",def:"Filters HTTP requests against attack patterns. Buys time before a patch; it does not fix the underlying flaw."},
{t:"Rate limiting",a:"",d:"Cloud & Infrastructure",def:"Capping how many requests a client can make in a window. The simplest defence against brute force, scraping, and abuse."},
{t:"API gateway",a:"",d:"Cloud & Infrastructure",def:"A single front door for APIs handling authentication, rate limits, routing, and logging, so services do not each reimplement them."},
{t:"Edge computing",a:"",d:"Cloud & Infrastructure",def:"Processing data near where it is produced rather than in a central cloud. Cuts latency and bandwidth; multiplies the number of devices to secure."},
{t:"Data residency",a:"Data sovereignty",d:"Cloud & Infrastructure",def:"Legal requirements about where data physically lives and which government can compel access to it. A cloud region choice with legal consequences."},
{t:"Egress cost / lock-in",a:"",d:"Cloud & Infrastructure",def:"Charges for moving data out of a cloud, and the dependence they create. A commercial concern that becomes a resilience concern."},
/* --- Endpoints & Systems --- */
{t:"Endpoint",a:"",d:"Endpoints & Systems",def:"Any device a person uses to reach the network — laptop, phone, tablet, server. Where most intrusions begin and where most detection now lives."},
{t:"Operating system",a:"OS",d:"Endpoints & Systems",def:"The software managing hardware, memory, and processes. Its permission model is the boundary attackers are usually trying to cross."},
{t:"Kernel",a:"",d:"Endpoints & Systems",def:"The core of the operating system, running with full hardware access. Code running here can hide from everything above it."},
{t:"User space vs kernel space",a:"",d:"Endpoints & Systems",def:"The separation between ordinary programs and privileged system code. Crossing from one to the other is the goal of local privilege escalation."},
{t:"Patch",a:"",d:"Endpoints & Systems",def:"A vendor fix for a bug or vulnerability. Applying them promptly prevents more breaches than any tool you can buy."},
{t:"Patch Tuesday",a:"",d:"Endpoints & Systems",def:"Microsoft's monthly release of security fixes, on the second Tuesday. Exploit development against those fixes typically follows within days."},
{t:"Hardening",a:"",d:"Endpoints & Systems",def:"Removing unnecessary services, accounts, and features and tightening what remains. Cheap, unglamorous, and highly effective."},
{t:"Baseline / benchmark",a:"CIS Benchmarks",d:"Endpoints & Systems",def:"A published, agreed secure configuration for a platform. Gives you something concrete to measure drift against."},
{t:"Golden image",a:"",d:"Endpoints & Systems",def:"A standard, pre-hardened system image every machine is built from, so security settings are the default rather than a follow-up task."},
{t:"Antivirus",a:"AV",d:"Endpoints & Systems",def:"Signature and heuristic detection of malicious files. Necessary, insufficient, and blind to fileless and living-off-the-land activity."},
{t:"EDR",a:"Endpoint Detection and Response",d:"Endpoints & Systems",def:"An agent recording process, file, and network behaviour on the endpoint, with the ability to alert, hunt, and isolate. The successor to antivirus."},
{t:"XDR",a:"Extended Detection and Response",d:"Endpoints & Systems",def:"Correlating endpoint telemetry with identity, email, and cloud signals in one place. Often just a vendor's bundle under a new name."},
{t:"MDM",a:"Mobile Device Management",d:"Endpoints & Systems",def:"Central enrolment and policy for phones and laptops — encryption, passcodes, app control, remote wipe."},
{t:"BYOD",a:"Bring Your Own Device",d:"Endpoints & Systems",def:"Staff using personal devices for work. Convenient, and it puts corporate data on hardware you do not control or get to inspect."},
{t:"Application allow-listing",a:"Whitelisting",d:"Endpoints & Systems",def:"Only approved executables may run. Extremely strong, operationally demanding, and impractical for developer machines."},
{t:"Full-disk encryption",a:"BitLocker, FileVault, LUKS",d:"Endpoints & Systems",def:"Encrypting the whole drive so a lost or stolen device gives up nothing. Protects data at rest, not a running unlocked machine."},
{t:"Secure Boot",a:"",d:"Endpoints & Systems",def:"Firmware refusing to load unsigned boot code, blocking bootkits before the operating system starts."},
{t:"UEFI / BIOS",a:"Firmware",d:"Endpoints & Systems",def:"The low-level code that starts the hardware. Rarely patched, hard to inspect, and highly persistent when compromised."},
{t:"Privilege separation",a:"",d:"Endpoints & Systems",def:"Running each component with only the rights it needs, so a compromise in one part does not hand over the whole system."},
{t:"Sudo / runas",a:"",d:"Endpoints & Systems",def:"Mechanisms for running a single command with elevated rights instead of working as an administrator all day. Also a valuable audit trail."},
{t:"Local admin rights",a:"",d:"Endpoints & Systems",def:"Full control of one machine. Removing standing local admin from ordinary users blocks a large share of malware outright."},
{t:"UAC",a:"User Account Control",d:"Endpoints & Systems",def:"Windows' prompt before elevated actions. A speed bump rather than a boundary — plenty of documented bypasses exist."},
{t:"Group Policy",a:"GPO",d:"Endpoints & Systems",def:"Windows' central mechanism for pushing configuration to domain machines. Also a superb attacker tool once domain admin is obtained."},
{t:"PowerShell",a:"",d:"Endpoints & Systems",def:"Windows' scripting and administration shell. Enormously useful to admins and attackers alike, which is why script block logging matters."},
{t:"SSH",a:"Secure Shell",d:"Endpoints & Systems",def:"Encrypted remote command-line access. Key-based authentication should replace passwords, and unmanaged authorised_keys entries are a persistence route."},
{t:"RDP",a:"Remote Desktop Protocol",d:"Endpoints & Systems",def:"Windows remote graphical access. Exposed to the internet, it is one of the most-attacked services in existence."},
{t:"Sysmon",a:"",d:"Endpoints & Systems",def:"A free Windows tool producing detailed process, network, and file telemetry. The cheapest meaningful upgrade to endpoint visibility."},
{t:"Event log",a:"",d:"Endpoints & Systems",def:"The operating system's record of what happened. Default retention is short, so shipping logs off-host is essential before an attacker clears them."},
{t:"Registry",a:"Windows Registry",d:"Endpoints & Systems",def:"Windows' central configuration database. A common place for malware to persist, since certain keys run automatically at boot or login."},
{t:"Scheduled task / cron",a:"",d:"Endpoints & Systems",def:"Built-in job schedulers. Legitimate everywhere, and among the first things to check for attacker persistence."},
{t:"Process injection",a:"",d:"Endpoints & Systems",def:"Running malicious code inside another, trusted process so it inherits that process's identity and looks normal."},
{t:"DLL hijacking",a:"",d:"Endpoints & Systems",def:"Placing a malicious library where a trusted program will load it first. Turns a legitimate signed application into the malware's launcher."},
{t:"Virtualisation",a:"",d:"Endpoints & Systems",def:"Running multiple isolated systems on one machine. The basis of cloud, and a safe place to detonate suspicious files."},
{t:"OT / ICS",a:"Operational Technology / Industrial Control Systems",d:"Endpoints & Systems",def:"Computers that run physical processes — plants, grids, pipelines. Long lifespans, no patch windows, and safety outranks confidentiality."},
{t:"SCADA",a:"Supervisory Control and Data Acquisition",d:"Endpoints & Systems",def:"The monitoring and control layer above industrial equipment. Historically built for isolated networks and now, unhelpfully, often reachable."},
{t:"IoT",a:"Internet of Things",d:"Endpoints & Systems",def:"Networked physical devices — cameras, sensors, meters. Weak defaults, rare updates, and long deployments make them ideal botnet recruits."},
{t:"Firmware update",a:"",d:"Endpoints & Systems",def:"Replacing the low-level software on a device. Often manual, sometimes unsigned, and the reason many devices stay vulnerable for years."},
{t:"End-of-life",a:"EOL / unsupported",d:"Endpoints & Systems",def:"Software the vendor no longer patches. Every future vulnerability in it stays open permanently, so EOL is a security deadline, not an IT one."},
/* --- Defense & Operations --- */
{t:"SOC",a:"Security Operations Centre",d:"Defense & Operations",def:"The team and tooling that monitor, triage, and respond to security events. In-house, outsourced, or a mix."},
{t:"SIEM",a:"Security Information and Event Management",d:"Defense & Operations",def:"Central log collection, correlation, and alerting. Only as good as the sources feeding it and the rules written on top."},
{t:"SOAR",a:"Security Orchestration, Automation and Response",d:"Defense & Operations",def:"Automating repetitive response steps through playbooks — enrich, contain, notify — so analysts handle the judgement calls."},
{t:"Detection engineering",a:"",d:"Defense & Operations",def:"Treating detections as code: written, tested, version-controlled, and measured. The shift from buying alerts to building them."},
{t:"Detection as code",a:"",d:"Defense & Operations",def:"Managing detection rules in a repository with review and CI, so changes are traceable and testable like any other software."},
{t:"Sigma",a:"",d:"Defense & Operations",def:"A vendor-neutral format for writing detection rules that can be converted to run on different SIEMs. The shared language for sharing detections."},
{t:"YARA",a:"",d:"Defense & Operations",def:"A pattern-matching language for identifying malware families by content. Widely used in threat hunting and malware triage."},
{t:"True / false positive",a:"",d:"Defense & Operations",def:"A real detection versus a false alarm. False positive volume, not detection coverage, is what usually breaks a SOC."},
{t:"Alert fatigue",a:"",d:"Defense & Operations",def:"Analysts becoming numb to alerts through sheer volume. The mechanism by which a genuine alert is closed unread."},
{t:"Triage",a:"",d:"Defense & Operations",def:"Rapidly deciding whether an alert is real and how urgent. The gatekeeping step between monitoring and incident response."},
{t:"Threat hunting",a:"",d:"Defense & Operations",def:"Proactively searching for intrusions that no alert fired on, driven by a hypothesis rather than a queue."},
{t:"Incident response",a:"IR",d:"Defense & Operations",def:"The structured process of handling a confirmed security incident. Usually framed as prepare, detect, contain, eradicate, recover, learn."},
{t:"Containment",a:"",d:"Defense & Operations",def:"Stopping an incident spreading — isolating hosts, disabling accounts, blocking traffic — before removing the attacker."},
{t:"Eradication",a:"",d:"Defense & Operations",def:"Removing the attacker's access completely: malware, backdoors, added accounts, altered configuration, rogue tokens."},
{t:"Recovery",a:"",d:"Defense & Operations",def:"Bringing systems back into service safely and confirming the environment is clean. Restoring too early reinfects everything."},
{t:"Post-incident review",a:"Lessons learned, blameless postmortem",d:"Defense & Operations",def:"Examining what happened and why, without hunting individuals. Blame guarantees the next incident is reported late or not at all."},
{t:"Playbook / runbook",a:"",d:"Defense & Operations",def:"Written steps for a specific scenario. Their real value is that they work at three in the morning when nobody is thinking clearly."},
{t:"Tabletop exercise",a:"",d:"Defense & Operations",def:"A discussion-based rehearsal of an incident scenario. Cheap, and reliably exposes decision-making and communication gaps."},
{t:"Chain of custody",a:"",d:"Defense & Operations",def:"Documented handling of evidence from collection onwards. Break it and the evidence may be worthless in a legal proceeding."},
{t:"Digital forensics",a:"DFIR",d:"Defense & Operations",def:"Recovering and analysing digital evidence to establish what happened. Paired with incident response as one discipline."},
{t:"Order of volatility",a:"",d:"Defense & Operations",def:"Collect the most perishable evidence first — memory, then network state, then disk. Pulling the plug destroys the most useful data."},
{t:"Memory forensics",a:"",d:"Defense & Operations",def:"Analysing RAM for injected code, decrypted secrets, and running processes that never touched disk. Often the only place fileless malware exists."},
{t:"Timeline analysis",a:"",d:"Defense & Operations",def:"Building an ordered sequence of events across sources to reconstruct an intrusion and find the initial access point."},
{t:"Log retention",a:"",d:"Defense & Operations",def:"How long logs are kept. Intrusions are often found months later, so short retention quietly makes investigation impossible."},
{t:"Telemetry",a:"",d:"Defense & Operations",def:"The raw signals systems emit. Detection is limited by telemetry — you cannot alert on something nobody records."},
{t:"Baseline / anomaly detection",a:"",d:"Defense & Operations",def:"Learning what normal looks like and alerting on deviation. Catches novel attacks and generates plenty of noise doing it."},
{t:"UEBA",a:"User and Entity Behaviour Analytics",d:"Defense & Operations",def:"Behavioural profiling of users and machines to spot compromised accounts and insiders acting out of character."},
{t:"Deception technology",a:"Honeypot, canary token",d:"Defense & Operations",def:"Fake systems, files, or credentials that nothing legitimate should ever touch. Very low false-positive rate when they trigger."},
{t:"Vulnerability management",a:"",d:"Defense & Operations",def:"Finding, prioritising, fixing, and verifying vulnerabilities as a continuous cycle. Prioritisation is the hard part, not scanning."},
{t:"Vulnerability scanner",a:"",d:"Defense & Operations",def:"A tool that checks systems against a database of known flaws. Reports what might be vulnerable, not what is exploitable in your context."},
{t:"Attack surface management",a:"ASM / EASM",d:"Defense & Operations",def:"Continuously discovering what of yours is exposed to the internet, including assets nobody remembered owning."},
{t:"Purple teaming",a:"",d:"Defense & Operations",def:"Red and blue working together, running known techniques to check whether detection actually fires. Improvement rather than scorekeeping."},
{t:"Breach and attack simulation",a:"BAS",d:"Defense & Operations",def:"Automated, continuous safe replay of attack techniques to validate that controls and detections still work after changes."},
{t:"MTTD / MTTR",a:"Mean Time to Detect / Respond",d:"Defense & Operations",def:"How long detection and response take on average. The two operational metrics that most reflect real-world damage."},
{t:"Runbook automation",a:"",d:"Defense & Operations",def:"Turning repeated manual response steps into scripts or workflows. Consistency under pressure, and a free audit trail."},
{t:"On-call / escalation",a:"",d:"Defense & Operations",def:"Defined rotas and paths for raising an incident out of hours. An unclear escalation path costs more time than any tool saves."},
{t:"Crisis communications",a:"",d:"Defense & Operations",def:"Deciding in advance who says what to staff, customers, regulators, and press. Prepared badly, it turns an incident into a reputational event."},
{t:"Business continuity",a:"BCP",d:"Defense & Operations",def:"How the organisation keeps operating during disruption, including manual fallbacks. Broader than technical disaster recovery."},
/* --- Governance, Risk & Compliance --- */
{t:"CIA triad",a:"Confidentiality, Integrity, Availability",d:"Governance, Risk & Compliance",def:"The three properties security exists to protect. Most controls trade one against another, and naming which one you are protecting sharpens the argument."},
{t:"Non-repudiation",a:"",d:"Governance, Risk & Compliance",def:"Being able to prove someone took an action so they cannot credibly deny it. What signatures and tamper-evident logs provide."},
{t:"Defence in depth",a:"",d:"Governance, Risk & Compliance",def:"Layering independent controls so no single failure is fatal. Assumes each layer will eventually fail, because it will."},
{t:"Risk appetite / tolerance",a:"",d:"Governance, Risk & Compliance",def:"How much risk leadership is willing to accept. Without it stated, every risk decision becomes an argument."},
{t:"Risk register",a:"",d:"Governance, Risk & Compliance",def:"The recorded list of known risks with owners, ratings, and treatment. Useful when actively reviewed, decorative when not."},
{t:"Risk treatment",a:"Accept, mitigate, transfer, avoid",d:"Governance, Risk & Compliance",def:"The four things you can do about a risk. Accepting is legitimate — provided someone with authority signs it."},
{t:"Inherent vs residual risk",a:"",d:"Governance, Risk & Compliance",def:"Risk before controls versus what remains after them. Residual risk is the number leadership should actually be shown."},
{t:"Control",a:"",d:"Governance, Risk & Compliance",def:"A safeguard reducing risk. Categorised as preventive, detective, or corrective, and as technical, administrative, or physical."},
{t:"Compensating control",a:"",d:"Governance, Risk & Compliance",def:"An alternative measure when the required control is not feasible. Must genuinely meet the intent, not merely be documented as if it does."},
{t:"Policy / standard / procedure",a:"",d:"Governance, Risk & Compliance",def:"Policy states intent, standards set specific requirements, procedures give the steps. Collapsing them into one document is why nobody follows any of them."},
{t:"ISO/IEC 27001",a:"",d:"Governance, Risk & Compliance",def:"The international standard for an information security management system, and certifiable. It assesses the management system, not the technical strength."},
{t:"NIST CSF",a:"NIST Cybersecurity Framework",d:"Governance, Risk & Compliance",def:"A voluntary framework organised around Govern, Identify, Protect, Detect, Respond, Recover. Widely used as a common structure for maturity conversations."},
{t:"NIST SP 800-53 / 800-171",a:"",d:"Governance, Risk & Compliance",def:"Detailed US federal control catalogues — 800-53 for federal systems, 800-171 for contractors handling controlled unclassified information."},
{t:"SOC 2",a:"",d:"Governance, Risk & Compliance",def:"An audit report on a service provider's controls against trust criteria. Type I is a point in time; Type II covers a period and is the one to ask for."},
{t:"PCI DSS",a:"Payment Card Industry Data Security Standard",d:"Governance, Risk & Compliance",def:"Mandatory rules for anyone handling payment card data. Contractual rather than statutory, and enforced by fines and lost processing rights."},
{t:"GDPR",a:"General Data Protection Regulation",d:"Governance, Risk & Compliance",def:"The EU regulation governing personal data. Extraterritorial, principles-based, and backed by fines up to four percent of global turnover."},
{t:"Personal data / PII",a:"Personally Identifiable Information",d:"Governance, Risk & Compliance",def:"Data relating to an identifiable person. GDPR's definition is deliberately broad and includes IP addresses and device identifiers."},
{t:"Special category data",a:"Sensitive personal data",d:"Governance, Risk & Compliance",def:"Health, biometrics, ethnicity, religion, sexuality, politics, union membership. Higher legal protection and higher real-world harm if exposed."},
{t:"Lawful basis",a:"",d:"Governance, Risk & Compliance",def:"The legal justification for processing personal data — consent, contract, legal obligation, vital interests, public task, legitimate interests."},
{t:"Data minimisation",a:"",d:"Governance, Risk & Compliance",def:"Collect only what you need and keep it only as long as you need it. The control that shrinks breach impact more than any tool."},
{t:"Purpose limitation",a:"",d:"Governance, Risk & Compliance",def:"Data collected for one stated purpose may not be quietly reused for another. The principle most often broken by analytics and AI training."},
{t:"Data subject rights",a:"DSAR",d:"Governance, Risk & Compliance",def:"Individuals' rights to access, correct, delete, or port their data, with statutory response deadlines."},
{t:"DPIA",a:"Data Protection Impact Assessment",d:"Governance, Risk & Compliance",def:"A required assessment before high-risk processing, documenting risks to people and how they are mitigated. Best done at design, not sign-off."},
{t:"Privacy by design",a:"",d:"Governance, Risk & Compliance",def:"Building privacy protections into a system from the start, with privacy-protective defaults. A GDPR obligation, not a philosophy."},
{t:"Anonymisation vs pseudonymisation",a:"",d:"Governance, Risk & Compliance",def:"Anonymised data cannot be linked back and leaves scope; pseudonymised data can be re-linked with a key and is still personal data."},
{t:"Re-identification",a:"",d:"Governance, Risk & Compliance",def:"Reconnecting supposedly anonymous records to people, usually by combining datasets. The reason true anonymisation is much harder than it sounds."},
{t:"Differential privacy",a:"",d:"Governance, Risk & Compliance",def:"Adding calibrated statistical noise so aggregate results are useful while no individual's presence can be inferred."},
{t:"Breach notification",a:"",d:"Governance, Risk & Compliance",def:"The legal duty to report certain breaches within a deadline — 72 hours to a regulator under GDPR, and to affected people if the risk is high."},
{t:"Data classification",a:"",d:"Governance, Risk & Compliance",def:"Labelling data by sensitivity so handling rules can follow the label. Three or four tiers work; ten do not."},
{t:"DLP",a:"Data Loss Prevention",d:"Governance, Risk & Compliance",def:"Tooling that spots and blocks sensitive data leaving. Good at accidents, weak against a determined insider."},
{t:"Retention schedule",a:"",d:"Governance, Risk & Compliance",def:"How long each category of data is kept before deletion. Data you deleted on schedule cannot be breached or subpoenaed."},
{t:"Third-party risk",a:"TPRM / vendor risk",d:"Governance, Risk & Compliance",def:"Managing the risk suppliers introduce. You can outsource the processing, but not the accountability."},
{t:"Due diligence",a:"",d:"Governance, Risk & Compliance",def:"Assessing a supplier's security before signing. Questionnaires are the norm; evidence and audit rights are what actually matter."},
{t:"SBOM",a:"Software Bill of Materials",d:"Governance, Risk & Compliance",def:"A machine-readable inventory of components in a piece of software. Turns a new vulnerability disclosure into a lookup rather than a scramble."},
{t:"CVE / CVSS",a:"Common Vulnerabilities and Exposures / Scoring System",d:"Governance, Risk & Compliance",def:"CVE is the unique identifier for a known flaw; CVSS scores its severity out of ten. CVSS ignores your context, so it is an input, not a decision."},
{t:"KEV",a:"Known Exploited Vulnerabilities catalogue",d:"Governance, Risk & Compliance",def:"CISA's list of vulnerabilities confirmed exploited in the wild. A far better patching priority than CVSS score alone."},
{t:"EPSS",a:"Exploit Prediction Scoring System",d:"Governance, Risk & Compliance",def:"A probability that a vulnerability will be exploited in the next 30 days. Pairs well with CVSS to cut patch backlogs to something achievable."},
{t:"Audit trail",a:"",d:"Governance, Risk & Compliance",def:"A tamper-evident record of who did what and when. Required by most frameworks and indispensable during an investigation."},
{t:"Segregation of duties",a:"SoD",d:"Governance, Risk & Compliance",def:"Splitting a sensitive process so no one person can complete it alone. The standard control against both fraud and single-point mistakes."},
{t:"Security awareness training",a:"",d:"Governance, Risk & Compliance",def:"Teaching staff to recognise and report attacks. Effective when it is short, frequent, and safe to report to; useless as an annual slideshow."},
/* --- AI & Emerging Tech --- */
{t:"Machine learning",a:"ML",d:"AI & Emerging Tech",def:"Systems that derive rules from data rather than being programmed with them. The behaviour reflects the training data, including its errors and bias."},
{t:"Large language model",a:"LLM",d:"AI & Emerging Tech",def:"A model trained on vast text to predict likely continuations. Fluent by construction, and fluency is not the same as being correct."},
{t:"Training data",a:"",d:"AI & Emerging Tech",def:"The corpus a model learns from. Its provenance, licensing, and bias become properties of the finished system."},
{t:"Inference",a:"",d:"AI & Emerging Tech",def:"Running a trained model to get an output. Where cost, latency, and most data-exposure questions actually live."},
{t:"Prompt",a:"",d:"AI & Emerging Tech",def:"The instruction and context given to a model. In most current systems it is also, unhelpfully, the security boundary."},
{t:"System prompt",a:"",d:"AI & Emerging Tech",def:"Standing instructions set by the developer ahead of user input. Treat it as configuration, never as a secret — it leaks."},
{t:"Context window",a:"",d:"AI & Emerging Tech",def:"How much text a model can consider at once. Anything beyond it is dropped or summarised, which quietly changes behaviour."},
{t:"Token",a:"",d:"AI & Emerging Tech",def:"The chunk of text a model processes, roughly a word fragment. The unit of both pricing and context limits."},
{t:"Hallucination",a:"Confabulation",d:"AI & Emerging Tech",def:"A confident, fluent, wrong output. Not a bug to be patched out but a property of prediction, which is why verification has to be designed in."},
{t:"Prompt injection",a:"",d:"AI & Emerging Tech",def:"Hostile instructions hidden in content a model reads, hijacking its behaviour. The defining security problem of LLM applications."},
{t:"Indirect prompt injection",a:"",d:"AI & Emerging Tech",def:"Injection delivered through a document, web page, or email the model retrieves, so the attacker never talks to the system directly."},
{t:"Jailbreak",a:"",d:"AI & Emerging Tech",def:"Framing that persuades a model past its safety training. Distinct from prompt injection, which targets the application's instructions."},
{t:"Data poisoning",a:"",d:"AI & Emerging Tech",def:"Corrupting training or retrieval data so the model learns something the attacker chose. Very hard to detect after the fact."},
{t:"Model inversion / membership inference",a:"",d:"AI & Emerging Tech",def:"Extracting training data, or proving a specific record was in the training set, by probing the model. A privacy problem for models trained on personal data."},
{t:"Model extraction",a:"Model stealing",d:"AI & Emerging Tech",def:"Reconstructing a proprietary model by querying it enough times to train a copy of its behaviour."},
{t:"Adversarial example",a:"",d:"AI & Emerging Tech",def:"Input perturbed slightly so a model misclassifies it while a person sees nothing unusual. The classic attack on vision systems."},
{t:"RAG",a:"Retrieval-Augmented Generation",d:"AI & Emerging Tech",def:"Fetching relevant documents and giving them to a model as context. It grounds answers — and makes every retrievable document an injection surface."},
{t:"Vector database",a:"Embedding store",d:"AI & Emerging Tech",def:"Storage for numeric representations of text so similar meaning can be found by proximity. The retrieval half of RAG, and it inherits the source's access rules only if you make it."},
{t:"Embedding",a:"",d:"AI & Emerging Tech",def:"A numeric representation capturing meaning, so similar things sit close together. Not anonymised — original text can often be approximately recovered."},
{t:"Fine-tuning",a:"",d:"AI & Emerging Tech",def:"Further training a base model on specific data to specialise it. Anything in that data is baked into the weights and cannot be selectively deleted."},
{t:"Guardrails",a:"",d:"AI & Emerging Tech",def:"Filters and policies around a model's inputs and outputs. Necessary, probabilistic, and not a substitute for real authorisation checks."},
{t:"Human in the loop",a:"HITL",d:"AI & Emerging Tech",def:"Requiring a person to approve consequential AI-driven actions. Only meaningful if the reviewer has the time and information to genuinely disagree."},
{t:"Agentic AI",a:"AI agent",d:"AI & Emerging Tech",def:"A model given tools and the autonomy to take multi-step actions. It converts a text-generation risk into a systems-and-permissions risk."},
{t:"Tool use / function calling",a:"",d:"AI & Emerging Tech",def:"Letting a model invoke external functions or APIs. Whatever the tool can do, a successful prompt injection can do."},
{t:"MCP",a:"Model Context Protocol",d:"AI & Emerging Tech",def:"An open standard for connecting models to tools and data sources. Each connected server is a new trust relationship to review."},
{t:"Model card",a:"",d:"AI & Emerging Tech",def:"Documentation of a model's intended use, training data, evaluation, and limitations. The AI equivalent of a datasheet."},
{t:"AI red teaming",a:"",d:"AI & Emerging Tech",def:"Deliberately probing a model or AI system for harmful, biased, or unsafe behaviour before users find it."},
{t:"Explainability",a:"XAI",d:"AI & Emerging Tech",def:"Being able to say why a model produced a given output. Increasingly a legal requirement for decisions affecting people."},
{t:"Algorithmic bias",a:"",d:"AI & Emerging Tech",def:"Systematic unfairness in outputs, usually inherited from data or objectives. A safety and legal problem, not only an accuracy one."},
{t:"EU AI Act",a:"",d:"AI & Emerging Tech",def:"The EU's risk-tiered regulation of AI systems, with outright bans at the top and obligations scaling with risk. Extraterritorial, like GDPR."},
{t:"Deepfake",a:"Synthetic media",d:"AI & Emerging Tech",def:"AI-generated audio, image, or video imitating a real person. Already routine in payment fraud and executive impersonation."},
{t:"Content provenance",a:"C2PA",d:"AI & Emerging Tech",def:"Cryptographically signed metadata recording how a piece of media was made and edited. An attempt to make authenticity checkable rather than assumed."},
{t:"Watermarking",a:"",d:"AI & Emerging Tech",def:"Embedding a detectable signal in AI-generated output. Helpful at scale, and generally removable by anyone who wants to remove it."},
{t:"Shadow AI",a:"",d:"AI & Emerging Tech",def:"Staff using AI tools without approval, often pasting confidential data into them. The current form of shadow IT, moving faster."},
{t:"Blockchain",a:"Distributed ledger",d:"AI & Emerging Tech",def:"An append-only ledger replicated across many parties. Strong integrity guarantees; no confidentiality, and no help if the data entered was wrong."},
{t:"Smart contract",a:"",d:"AI & Emerging Tech",def:"Code executing automatically on a blockchain. Immutable once deployed, which means bugs are permanent and expensive."},
{t:"Quantum computing",a:"",d:"AI & Emerging Tech",def:"Computation using quantum states, able in principle to break RSA and elliptic-curve cryptography. The reason post-quantum migration is starting now."},
{t:"Confidential computing",a:"TEE / enclave",d:"AI & Emerging Tech",def:"Processing data inside a hardware-protected enclave so even the host operating system cannot read it. Closes the in-use gap left by encryption at rest and in transit."},
/* --- Dev & Delivery --- */
{t:"Repository",a:"Repo",d:"Dev & Delivery",def:"The project folder plus its entire history of changes. Everything else in version control is an operation on a repository."},
{t:"Version control",a:"Git, VCS",d:"Dev & Delivery",def:"A system that records every change to a codebase, who made it and why, and lets you go back. Git is the near-universal one; GitHub and GitLab are hosts for it."},
{t:"Clone",a:"",d:"Dev & Delivery",def:"Copying a remote repository, including its full history, onto your own machine. The first command of most working days."},
{t:"Fork",a:"",d:"Dev & Delivery",def:"Your own server-side copy of someone else's repository, so you can change it without write access to the original and propose the change back."},
{t:"Branch",a:"",d:"Dev & Delivery",def:"A named line of work running alongside the main one. It lets you build or break something without affecting what everyone else is using."},
{t:"main / master",a:"Default branch",d:"Dev & Delivery",def:"The branch treated as the source of truth. Most projects protect it so nothing lands without review."},
{t:"Commit",a:"",d:"Dev & Delivery",def:"A saved, described snapshot of your changes, recorded permanently in the history. The unit of work everything else — review, revert, blame — operates on."},
{t:"Commit message",a:"",d:"Dev & Delivery",def:"The note explaining what changed and why. The why is the part future-you cannot reconstruct from the diff."},
{t:"Staging area",a:"Index",d:"Dev & Delivery",def:"Git's holding pen between your working files and a commit. `git add` puts changes there so you can commit some edits and not others."},
{t:"Push",a:"",d:"Dev & Delivery",def:"Sending your local commits up to the remote repository so others — and any deployment pipeline — can see them. Nothing you have not pushed exists to anyone else."},
{t:"Pull",a:"",d:"Dev & Delivery",def:"Fetching changes from the remote and merging them into your branch. Pull before you start work, or you will be resolving conflicts later."},
{t:"Fetch",a:"",d:"Dev & Delivery",def:"Downloading remote changes without applying them to your working copy. The cautious half of a pull, when you want to look before you merge."},
{t:"Sync",a:"",d:"Dev & Delivery",def:"Bringing two copies into agreement — usually a pull followed by a push, so local and remote match. In GUIs it is often one button doing both."},
{t:"Remote",a:"origin, upstream",d:"Dev & Delivery",def:"A named repository your local copy talks to. `origin` is normally your own copy; `upstream` is the original you forked from."},
{t:"Merge",a:"",d:"Dev & Delivery",def:"Combining one branch's changes into another. Git does it automatically unless both sides edited the same lines."},
{t:"Merge conflict",a:"",d:"Dev & Delivery",def:"Two branches changed the same lines and Git refuses to guess. You pick what the file should say, then commit the resolution."},
{t:"Rebase",a:"",d:"Dev & Delivery",def:"Replaying your commits on top of an updated branch to give a straight history instead of a merge. Never rebase a branch other people have already pulled."},
{t:"Pull request",a:"PR / merge request / MR",d:"Dev & Delivery",def:"A proposal to merge one branch into another, with a place to discuss and review it first. Where code review, CI checks and approvals happen."},
{t:"Code review",a:"",d:"Dev & Delivery",def:"Another engineer reading a change before it lands. The cheapest place to catch both bugs and security mistakes."},
{t:"Diff",a:"",d:"Dev & Delivery",def:"The line-by-line difference between two versions — what was added, removed and changed. What you actually review, rather than the whole file."},
{t:"HEAD",a:"",d:"Dev & Delivery",def:"A pointer to the commit you currently have checked out. `HEAD~1` is the one before it."},
{t:"Tag",a:"",d:"Dev & Delivery",def:"A permanent name pinned to a specific commit, normally a release like v2.1.0. Unlike a branch, it does not move."},
{t:"Release",a:"",d:"Dev & Delivery",def:"A tagged, packaged version handed to users, usually with notes and built artifacts attached."},
{t:"Revert",a:"",d:"Dev & Delivery",def:"Creating a new commit that undoes an earlier one, leaving the history intact. The safe way to back out a change that is already public."},
{t:"Reset",a:"",d:"Dev & Delivery",def:"Moving your branch pointer backwards, optionally throwing away work. Powerful locally, destructive if you force-push the result."},
{t:"Cherry-pick",a:"",d:"Dev & Delivery",def:"Copying one specific commit onto another branch. How an urgent fix reaches a release branch without dragging everything else with it."},
{t:"Stash",a:"",d:"Dev & Delivery",def:"Parking uncommitted changes temporarily so you can switch context, then bringing them back."},
{t:".gitignore",a:"",d:"Dev & Delivery",def:"A list of paths Git should never track — build output, local config, secrets. The first line of defence against committing a key by accident."},
{t:"Monorepo",a:"",d:"Dev & Delivery",def:"Many projects in one repository, sharing tooling and history. Simpler coordination, heavier tooling; the alternative is many small repos."},
{t:"CI",a:"Continuous Integration",d:"Dev & Delivery",def:"Automatically building and testing every change as it is pushed, so problems surface in minutes rather than at release."},
{t:"CD",a:"Continuous Delivery / Deployment",d:"Dev & Delivery",def:"Delivery keeps every change releasable at a button press; deployment ships it automatically once checks pass. The two are often written as one and mean different things."},
{t:"Pipeline",a:"Workflow, GitHub Actions",d:"Dev & Delivery",def:"The scripted sequence that runs on a push — install, lint, test, build, scan, deploy. It holds real credentials, which makes it a genuine attack surface."},
{t:"Build",a:"",d:"Dev & Delivery",def:"Turning source code into something runnable — compiled, bundled, containerised. A build that only works on one machine is a bug."},
{t:"Artifact",a:"",d:"Dev & Delivery",def:"The output of a build: a binary, a container image, a zipped bundle. What actually gets deployed, as opposed to the source."},
{t:"Deploy",a:"Ship, release to production",d:"Dev & Delivery",def:"Putting a built version onto the servers where real users reach it. Small, frequent deploys are safer than big rare ones, because there is less to unpick when one goes wrong."},
{t:"Environment",a:"dev / staging / production",d:"Dev & Delivery",def:"Separate copies of the system for building, testing and real use. Staging should resemble production closely enough that passing there means something."},
{t:"Production",a:"Prod",d:"Dev & Delivery",def:"The live system real people depend on. Every rule about review, backups and change control exists because of what happens here."},
{t:"Rollback",a:"",d:"Dev & Delivery",def:"Returning to the previous working version after a bad deploy. Knowing you can roll back in one step is what makes frequent deploys reasonable."},
{t:"Blue-green / canary deploy",a:"",d:"Dev & Delivery",def:"Two ways to release safely: run two full environments and switch traffic, or send the new version to a small slice of users first and watch."},
{t:"Feature flag",a:"Toggle",d:"Dev & Delivery",def:"A switch that turns functionality on or off without a deploy. Separates releasing code from releasing the feature — and stale flags become their own mess."},
{t:"Hotfix",a:"",d:"Dev & Delivery",def:"An urgent fix taken straight to production outside the normal cycle. Legitimate, and worth logging, because it skipped the usual checks."},
{t:"Semantic versioning",a:"SemVer",d:"Dev & Delivery",def:"MAJOR.MINOR.PATCH, where major means a breaking change, minor adds features, patch fixes bugs. It tells you how nervous to be about upgrading."},
{t:"Breaking change",a:"",d:"Dev & Delivery",def:"A change that stops existing users' code or configuration working. It needs a major version bump and a note, not a quiet release."},
{t:"Dependency",a:"Package, library",d:"Dev & Delivery",def:"Third-party code your project relies on. Most of a modern application is dependencies, which is why supply chain security is a real concern."},
{t:"Package manager",a:"npm, pip, cargo, apt",d:"Dev & Delivery",def:"The tool that installs and updates dependencies. Also the channel a typosquatted or hijacked package arrives through."},
{t:"Lockfile",a:"package-lock.json, requirements.txt",d:"Dev & Delivery",def:"A record of the exact dependency versions installed, so every machine and every build gets the same ones. Commit it."},
{t:"Environment variable",a:"env var, .env",d:"Dev & Delivery",def:"Configuration passed to a program at runtime instead of written into the code. Where secrets belong in development — and `.env` belongs in `.gitignore`."},
{t:"Linter / formatter",a:"",d:"Dev & Delivery",def:"Tools that flag likely mistakes and enforce consistent style automatically. They end style arguments and catch a surprising number of bugs."},
{t:"Unit / integration test",a:"",d:"Dev & Delivery",def:"Unit tests check one piece in isolation; integration tests check the pieces working together. You need both, and integration tests are the ones people skip."},
{t:"Regression",a:"",d:"Dev & Delivery",def:"Something that used to work and now does not. Regression tests exist so the same bug cannot come back twice unnoticed."},
{t:"Refactor",a:"",d:"Dev & Delivery",def:"Restructuring code without changing what it does. If behaviour changed, it was not a refactor, and it needs reviewing as a real change."},
{t:"Technical debt",a:"",d:"Dev & Delivery",def:"Shortcuts taken to ship faster that cost more later. Sometimes a good trade — but only if someone writes down that it was taken."},
{t:"API",a:"Application Programming Interface",d:"Dev & Delivery",def:"The defined way one piece of software talks to another. Everything in the library section of this site is reached through one."},
{t:"REST / GraphQL",a:"",d:"Dev & Delivery",def:"Two API styles: REST exposes resources at URLs and you take what each returns; GraphQL exposes one endpoint and you ask for exactly the fields you want."},
{t:"API endpoint",a:"Route",d:"Dev & Delivery",def:"A specific URL an API exposes for one operation. Each one needs its own authorisation check — this is where broken access control usually lives."},
{t:"Webhook",a:"",d:"Dev & Delivery",def:"A URL you register so another service can push events to you as they happen, instead of you polling. Verify the signature, or anyone can post to it."},
{t:"SDK / CLI",a:"Software Development Kit / Command Line Interface",d:"Dev & Delivery",def:"A library that wraps an API in your language, and a terminal tool that wraps it for humans and scripts. Usually easier and safer than hand-rolling HTTP calls."},
{t:"JSON / YAML",a:"",d:"Dev & Delivery",def:"The two everyday data formats: JSON for APIs, YAML for configuration. YAML's indentation and loose typing cause more outages than they should."},
{t:"Rate limit",a:"Quota",d:"Dev & Delivery",def:"How many API calls you are allowed in a window. Read it before writing the loop, cache the responses, and handle the 429 rather than retrying blindly."},
{t:"Idempotent",a:"",d:"Dev & Delivery",def:"An operation that gives the same result whether you run it once or five times. What makes safe retries possible."},
{t:"Observability",a:"Logs, metrics, traces",d:"Dev & Delivery",def:"Being able to tell what a running system is doing from the outside. Logs say what happened, metrics count it, traces follow one request across services."},
{t:"SLA / SLO",a:"Service Level Agreement / Objective",d:"Dev & Delivery",def:"The availability you promise contractually, and the internal target you actually manage to. The objective should be stricter than the agreement."},
{t:"Upstream / downstream",a:"",d:"Dev & Delivery",def:"Upstream is the project or service you depend on; downstream is whoever depends on you. Vulnerabilities travel downstream, fixes come from upstream."},
{t:"Deprecation",a:"EOL notice",d:"Dev & Delivery",def:"Formal warning that something will be removed, with a date. The window in which to migrate calmly rather than in an incident."},
{t:"Documentation",a:"README, docs",d:"Dev & Delivery",def:"The instructions that let someone else run, use or fix the thing. A project without a README is a project only its author can operate."},
/* --- Compute & Hardware --- */
{t:"CPU",a:"Central Processing Unit",d:"Compute & Hardware",def:"The general-purpose processor that runs the operating system and most software. Very fast at doing one complicated thing after another."},
{t:"GPU",a:"Graphics Processing Unit",d:"Compute & Hardware",def:"A processor with thousands of simple cores built to do the same operation on huge amounts of data at once. Made for graphics, now the engine of machine learning."},
{t:"CPU vs GPU",a:"",d:"Compute & Hardware",def:"A CPU is a few very fast generalists; a GPU is thousands of narrow specialists working in step. If your problem is the same maths repeated across a big array, the GPU wins by orders of magnitude."},
{t:"TPU / NPU",a:"Tensor / Neural Processing Unit",d:"Compute & Hardware",def:"Chips designed specifically for neural network maths. Google's TPUs run in its cloud; NPUs now ship inside phones and laptops for on-device inference."},
{t:"ASIC / FPGA",a:"",d:"Compute & Hardware",def:"An ASIC is a chip hard-wired for one job — fast, cheap at volume, unchangeable. An FPGA is reconfigurable hardware: slower, but you can rewrite what it is."},
{t:"Core / thread",a:"",d:"Compute & Hardware",def:"A core is an independent processing unit; a thread is one stream of instructions running on it. More cores means more genuinely simultaneous work."},
{t:"Clock speed",a:"GHz",d:"Compute & Hardware",def:"How many cycles a processor runs per second. A poor way to compare modern chips — architecture, cores and memory bandwidth matter more."},
{t:"Instruction set",a:"ISA — x86, ARM, RISC-V",d:"Compute & Hardware",def:"The vocabulary of operations a processor understands. x86 dominates servers and older PCs, ARM dominates mobile and now Apple and cloud silicon, RISC-V is the open alternative."},
{t:"System on a Chip",a:"SoC — not to be confused with a Security Operations Centre",d:"Compute & Hardware",def:"CPU, GPU, memory controller, and often a neural engine on a single piece of silicon. What phones, Raspberry Pis and Apple laptops are built on."},
{t:"RAM",a:"Random Access Memory",d:"Compute & Hardware",def:"Fast working memory holding what a program is actively using. Volatile — it empties on power loss, which is why memory forensics is time-critical."},
{t:"VRAM",a:"Video / GPU memory",d:"Compute & Hardware",def:"Memory attached directly to a GPU. It is the hard limit on model size: if the weights do not fit in VRAM, the model will not run, however fast the chip is."},
{t:"HBM",a:"High Bandwidth Memory",d:"Compute & Hardware",def:"Memory stacked next to the processor for enormous bandwidth. The scarce component in AI accelerators, and often the real bottleneck rather than compute."},
{t:"Cache",a:"L1 / L2 / L3",d:"Compute & Hardware",def:"Tiny, very fast memory close to the processor holding recently used data. Its timing behaviour leaks information, which is what Spectre-class attacks exploit."},
{t:"Memory bandwidth",a:"",d:"Compute & Hardware",def:"How fast data moves between memory and the processor. For large models, feeding the chip is harder than the arithmetic itself."},
{t:"Storage",a:"SSD / NVMe / HDD",d:"Compute & Hardware",def:"Persistent storage. NVMe SSDs are dramatically faster than spinning disks, which matters when loading model weights or replaying logs."},
{t:"PCIe",a:"Peripheral Component Interconnect Express",d:"Compute & Hardware",def:"The bus connecting GPUs, drives and network cards to the processor. Its generation and lane count cap how fast data reaches an accelerator."},
{t:"NVLink / InfiniBand",a:"Interconnect",d:"Compute & Hardware",def:"High-speed links between GPUs and between servers. Training a large model across many chips is limited by interconnect as much as by the chips."},
{t:"DMA",a:"Direct Memory Access",d:"Compute & Hardware",def:"Devices reading and writing system memory without going through the CPU. Fast, and a real attack path — a malicious Thunderbolt or PCIe device can read memory directly."},
{t:"Driver",a:"",d:"Compute & Hardware",def:"Software letting the operating system talk to hardware. Drivers run with kernel privileges, so a vulnerable or signed-but-malicious driver is a direct route to full control."},
{t:"BYOVD",a:"Bring Your Own Vulnerable Driver",d:"Compute & Hardware",def:"Installing a legitimately signed but flawed driver in order to abuse it for kernel access. A standard technique for disabling security tooling."},
{t:"FLOPS",a:"Floating point operations per second",d:"Compute & Hardware",def:"The standard measure of raw compute, quoted in teraflops or petaflops. Peak FLOPS is a ceiling, not a promise — real workloads rarely approach it."},
{t:"Throughput vs latency",a:"",d:"Compute & Hardware",def:"Throughput is how much work finishes per second; latency is how long one request takes. Batching raises throughput and worsens latency, and you usually have to choose."},
{t:"Parallelism",a:"Data / model / pipeline parallel",d:"Compute & Hardware",def:"Splitting work across chips — by data batch, by slicing the model itself, or by staging layers. How anything too large for one accelerator gets trained."},
{t:"Cluster / node",a:"",d:"Compute & Hardware",def:"A cluster is many machines working as one system; a node is a single machine in it. The unit of scale for both HPC and cloud training runs."},
{t:"HPC",a:"High Performance Computing",d:"Compute & Hardware",def:"Supercomputing for scientific workloads — climate models, genomics, simulation. Usually accessed through a batch scheduler rather than interactively."},
{t:"Job scheduler",a:"Slurm, PBS",d:"Compute & Hardware",def:"Software that queues and allocates cluster jobs across users. On shared research clusters, you submit a job and wait rather than running things directly."},
{t:"Precision",a:"FP32 / FP16 / BF16 / INT8",d:"Compute & Hardware",def:"How many bits represent each number. Lower precision means less memory and more speed, at some cost in accuracy — the central trade in running models cheaply."},
{t:"Quantisation",a:"",d:"Compute & Hardware",def:"Converting model weights to lower precision so they fit in less memory and run faster. It is how large models end up running on a laptop or a phone."},
{t:"Model weights",a:"Parameters",d:"Compute & Hardware",def:"The learned numbers that are the model. Their count and precision together decide how much VRAM you need — roughly two bytes per parameter at 16-bit."},
{t:"KV cache",a:"",d:"Compute & Hardware",def:"Stored intermediate values that let a language model generate each new token without recomputing the whole context. It grows with context length and eats VRAM."},
{t:"Tokens per second",a:"tok/s",d:"Compute & Hardware",def:"The practical speed measure for language model inference. Time to first token matters for how responsive it feels; tokens per second for how fast it finishes."},
{t:"Batch size",a:"",d:"Compute & Hardware",def:"How many inputs are processed together. Larger batches use hardware more efficiently and need more memory."},
{t:"Training vs inference",a:"",d:"Compute & Hardware",def:"Training builds the model and is enormously expensive but happens rarely; inference runs it and is cheap per call but happens constantly. Most lifetime cost ends up in inference."},
{t:"Fine-tuning vs LoRA",a:"Low-Rank Adaptation",d:"Compute & Hardware",def:"Full fine-tuning updates every weight and needs serious hardware; LoRA trains a small adapter alongside the frozen model and runs on a single consumer GPU."},
{t:"Distillation",a:"",d:"Compute & Hardware",def:"Training a small model to imitate a large one, trading a little quality for a lot of speed and cost. How capable models reach modest hardware."},
{t:"Edge inference",a:"On-device AI",d:"Compute & Hardware",def:"Running a model on the user's own hardware. No data leaves the device, which is a privacy gain and a hard limit on model size."},
{t:"GPU cloud",a:"Accelerator rental",d:"Compute & Hardware",def:"Renting accelerators by the hour rather than buying them. Cheaper to start, expensive to leave running — idle GPUs bill the same as busy ones."},
{t:"Spot / preemptible instance",a:"",d:"Compute & Hardware",def:"Discounted cloud capacity that can be taken back at short notice. Fine for checkpointed training, unusable for anything that cannot be interrupted."},
{t:"Bare metal vs virtualised",a:"",d:"Compute & Hardware",def:"A whole physical machine versus a share of one. Bare metal gives predictable performance and no noisy neighbours, at the cost of flexibility."},
{t:"GPU passthrough",a:"vGPU",d:"Compute & Hardware",def:"Giving a virtual machine direct or partitioned access to a physical GPU. Necessary for accelerated workloads in virtualised environments, and it weakens isolation."},
{t:"Datacentre",a:"Rack, colocation",d:"Compute & Hardware",def:"The building full of racked servers behind every cloud service. Physical security, power and cooling are as much a part of availability as any software control."},
{t:"PUE",a:"Power Usage Effectiveness",d:"Compute & Hardware",def:"Total facility power divided by the power actually reaching the computers. A PUE of 1.1 is efficient; anything near 2 means half the energy is going on cooling and losses."},
{t:"Thermal throttling",a:"",d:"Compute & Hardware",def:"Hardware slowing itself down to avoid overheating. The usual explanation when performance falls off partway through a long run."},
{t:"TDP",a:"Thermal Design Power",d:"Compute & Hardware",def:"The heat a chip is expected to produce, in watts. It drives cooling, power supply sizing and, at scale, the electricity bill."},
{t:"Embodied carbon",a:"",d:"Compute & Hardware",def:"The emissions from manufacturing hardware, before it is ever switched on. For short-lived devices it can outweigh the energy used running them."},
{t:"E-waste",a:"",d:"Compute & Hardware",def:"Discarded electronics, much of it exported and dismantled unsafely. Extending device life is both an environmental and a procurement decision."},
{t:"Right to repair",a:"",d:"Compute & Hardware",def:"Being able to fix and upgrade hardware you own — parts, tools and documentation. Directly affects how long a device stays secure and usable."},
{t:"Hardware root of trust",a:"",d:"Compute & Hardware",def:"An immutable component in silicon that everything else's trust chains back to. If it is compromised, no software check above it means anything."},
{t:"Spectre / Meltdown",a:"Speculative execution attacks",d:"Compute & Hardware",def:"Flaws in how processors guess ahead, letting one process read memory it should not. Fixes cost real performance and the class keeps producing new variants."},
{t:"Rowhammer",a:"",d:"Compute & Hardware",def:"Repeatedly accessing memory rows to flip bits in neighbouring ones through electrical interference. A software attack on a physical property of RAM."},
{t:"Cold boot attack",a:"",d:"Compute & Hardware",def:"Chilling memory chips so their contents survive a reboot long enough to be read, recovering encryption keys. Why locking a laptop is weaker than shutting it down."},
{t:"Evil maid attack",a:"",d:"Compute & Hardware",def:"Physical tampering with an unattended device — a modified bootloader, a hardware keylogger. Full-disk encryption alone does not stop it."},
{t:"Hardware implant",a:"",d:"Compute & Hardware",def:"A malicious component added during manufacture or shipping. Rare, extremely hard to detect, and the reason high-assurance procurement tracks provenance."},
{t:"Chip supply chain",a:"Fab, foundry",d:"Compute & Hardware",def:"The concentrated global pipeline that designs and manufactures processors. A geopolitical dependency as much as a technical one."},
/* --- Networking & Protocols (added) --- */
{t:"Access control",a:"",d:"Networking & Protocols",def:"Deciding who may reach which resource, and enforcing it. Everything else in identity — accounts, roles, permissions — exists to make this decision reliably."},
{t:"Access control list",a:"ACL",d:"Networking & Protocols",def:"A list attached to a resource naming who may use it and how. Simple, explicit, and still the model behind file permissions and router rules."},
{t:"Access matrix",a:"",d:"Networking & Protocols",def:"A grid of subjects against objects, with the permitted actions in each cell. Mostly a teaching model, but it is the mental picture behind every permissions system."},
{t:"Autonomous system",a:"AS",d:"Networking & Protocols",def:"A network, or set of networks, under one organisation's routing control, identified by an AS number. BGP is the language autonomous systems use to talk to each other."},
{t:"Bandwidth",a:"",d:"Networking & Protocols",def:"How much data a link can carry in a given time, usually in bits per second. Not the same as latency — a fat pipe can still be slow to respond."},
{t:"Banner",a:"",d:"Networking & Protocols",def:"The text a service announces when you connect to it, often naming the software and version. Free reconnaissance for an attacker, which is why banners get trimmed."},
{t:"BIND",a:"Berkeley Internet Name Domain",d:"Networking & Protocols",def:"The long-running reference implementation of DNS. Much of the internet's name resolution has run on it, so its vulnerabilities matter widely."},
{t:"Bridge",a:"",d:"Networking & Protocols",def:"A device that joins two network segments using the same protocol, passing frames between them. A switch is essentially a bridge with many ports."},
{t:"Broadcast",a:"",d:"Networking & Protocols",def:"Sending one message to every host on a network at once. Useful for discovery, and abusable — the Smurf attack is broadcast turned into a weapon."},
{t:"Broadcast address",a:"",d:"Networking & Protocols",def:"The address that reaches every host on a network segment. Traffic sent to it multiplies, which is why routers do not forward it across networks."},
{t:"Cell",a:"",d:"Networking & Protocols",def:"A fixed-length unit of data in ATM networks. Fixed size made switching fast in hardware, a design later overtaken by packet-based Ethernet."},
{t:"Circuit-switched network",a:"",d:"Networking & Protocols",def:"A network that reserves one continuous path for the whole conversation, as the old telephone system did. Reliable and wasteful; the internet chose packets instead."},
{t:"Packet",a:"",d:"Networking & Protocols",def:"A chunk of a message with a destination address attached, routed independently across the network. In IP networks packets are also called datagrams."},
{t:"Packet-switched network",a:"",d:"Networking & Protocols",def:"A network where each packet finds its own route to the destination and the pieces are reassembled on arrival. Resilient because there is no single fixed path to break."},
{t:"Datagram",a:"",d:"Networking & Protocols",def:"A self-contained packet that carries everything needed to be routed, without relying on any earlier exchange. The basis of connectionless protocols like UDP."},
{t:"Decapsulation",a:"",d:"Networking & Protocols",def:"Stripping a layer's header off a packet and handing the rest up the stack. The receiving half of what encapsulation does on the way out."},
{t:"Encapsulation",a:"",d:"Networking & Protocols",def:"Wrapping one protocol's data inside another's, so it can travel over a network that would not otherwise carry it. How tunnels and VPNs work."},
{t:"Tunnel",a:"",d:"Networking & Protocols",def:"A link built by wrapping one protocol inside another so traffic can cross a network that would not normally carry it. VPNs, IPsec and GRE are all tunnels."},
{t:"Client",a:"",d:"Networking & Protocols",def:"The system that asks for a service. A machine can be a client and a server at once — a proxy is both."},
{t:"Server",a:"",d:"Networking & Protocols",def:"The system that answers requests from clients. The word covers the software, the machine, or both, depending on who is talking."},
{t:"Session",a:"",d:"Networking & Protocols",def:"A connection between two hosts that lasts long enough to carry a conversation. Stealing one is cheaper for an attacker than stealing a password."},
{t:"Socket",a:"",d:"Networking & Protocols",def:"The combination of an IP address and a port that tells the network stack which application a data stream belongs to."},
{t:"Socket pair",a:"",d:"Networking & Protocols",def:"The four values that uniquely name a connection: source address and port, destination address and port. It is how a host keeps thousands of connections apart."},
{t:"Source port",a:"",d:"Networking & Protocols",def:"The temporary port a client picks for its end of a connection, usually a high number chosen at random. It changes with every connection."},
{t:"Ephemeral port",a:"",d:"Networking & Protocols",def:"A short-lived high-numbered port assigned to a client for one connection and released when it closes. Firewall rules that assume fixed ports break on these."},
{t:"Trusted ports",a:"",d:"Networking & Protocols",def:"Ports below 1024, which on Unix only a privileged account may bind. A weak assurance today, but it still shapes how services are started."},
{t:"Echo request / echo reply",a:"Ping",d:"Networking & Protocols",def:"The ICMP pair behind ping: a request asking whether a host is alive, and its reply. Blocked on many networks, which is why a silent host is not necessarily a dead one."},
{t:"ICMP",a:"Internet Control Message Protocol",d:"Networking & Protocols",def:"The protocol networks use to report errors and test reachability. It carries no user data, but it leaks a great deal about network shape."},
{t:"IP flood",a:"",d:"Networking & Protocols",def:"A denial of service that buries a host in more ping traffic than it can answer. Crude, loud, and still effective against small links."},
{t:"Ping sweep",a:"",d:"Networking & Protocols",def:"Pinging a whole range of addresses to find out which hosts exist. Usually the first step of mapping a network before probing it."},
{t:"Ping scan",a:"",d:"Networking & Protocols",def:"A check for which machines answer ICMP echo requests. The cheapest form of host discovery, and the easiest to spot in logs."},
{t:"Ping of death",a:"",d:"Networking & Protocols",def:"An old attack that sent an oversized ping packet to crash the receiving machine's input buffers. Long fixed, but the template — malformed input crashes a parser — never went away."},
{t:"Port scan",a:"",d:"Networking & Protocols",def:"Knocking on each port of a host in turn to see which services answer. The responses tell an attacker where to look for weaknesses."},
{t:"TCP full open scan",a:"",d:"Networking & Protocols",def:"A port scan that completes the full three-way handshake on every port. Accurate, noisy, and reliably logged by the target."},
{t:"TCP half open scan",a:"SYN scan",d:"Networking & Protocols",def:"A scan that sends a SYN and never finishes the handshake, judging the port by the reply. Faster and quieter than a full open scan."},
{t:"UDP scan",a:"",d:"Networking & Protocols",def:"Probing UDP ports to see which are open. Slow and unreliable, because silence can mean either an open port or a dropped packet."},
{t:"RPC scan",a:"",d:"Networking & Protocols",def:"A probe for which remote procedure call services a machine is running. Often the route to an unpatched service nobody knew was exposed."},
{t:"Distributed scan",a:"",d:"Networking & Protocols",def:"Scanning from many source addresses at once so no single one looks busy enough to alarm anyone. Detection has to correlate across sources."},
{t:"Fingerprinting",a:"OS fingerprinting",d:"Networking & Protocols",def:"Sending unusual packets and reading the replies to work out what operating system a host runs. Different stacks answer malformed input in different, recognisable ways."},
{t:"TCP fingerprinting",a:"",d:"Networking & Protocols",def:"Using odd combinations of TCP header flags to identify a remote operating system by how it responds."},
{t:"Network mapping",a:"",d:"Networking & Protocols",def:"Building an inventory of the hosts and services on a network. The same exercise for a defender protecting an estate and an attacker planning a route through it."},
{t:"Reconnaissance",a:"Recon",d:"Networking & Protocols",def:"The stage of an attack spent finding systems, mapping networks and looking for a way in — before anything is exploited."},
{t:"Traceroute",a:"tracert",d:"Networking & Protocols",def:"A tool that shows each hop a packet takes to a destination. It exposes the path, and often the internal structure of the network at the far end."},
{t:"Hop",a:"",d:"Networking & Protocols",def:"One handoff between routers on a packet's journey. Hop counts limit how far a packet can travel before being dropped."},
{t:"Time to live",a:"TTL",d:"Networking & Protocols",def:"A counter in a packet that drops by one at every hop and kills the packet at zero. It stops routing loops from running forever, and traceroute exploits it."},
{t:"Routing loop",a:"",d:"Networking & Protocols",def:"Two or more misconfigured routers passing the same packet back and forth. TTL is what eventually ends it."},
{t:"Distance vector",a:"",d:"Networking & Protocols",def:"A routing approach that picks paths by their cost in hops. Simple to run and slow to react to change; RIP is the classic example."},
{t:"Link state",a:"",d:"Networking & Protocols",def:"A routing approach where every router keeps a map of the whole area and calculates its own best paths. Faster to converge than distance vector; OSPF is the example."},
{t:"OSPF",a:"Open Shortest Path First",d:"Networking & Protocols",def:"A link-state routing protocol used inside an organisation's own network. Routers share a map of links and costs rather than just hop counts."},
{t:"RIP",a:"Routing Information Protocol",d:"Networking & Protocols",def:"An old distance-vector protocol that judges routes by hop count alone. Easy to configure and easy to fool."},
{t:"Split horizon",a:"",d:"Networking & Protocols",def:"A routing rule that stops a router advertising a route back to the neighbour it learned it from. It prevents a common class of routing loop."},
{t:"Poison reverse",a:"",d:"Networking & Protocols",def:"A stronger form of split horizon: the route is advertised back, but marked as unreachable. The unreachable claim is what kills the loop."},
{t:"Static routing",a:"",d:"Networking & Protocols",def:"Routing table entries typed in by hand that never change on their own. Predictable and unforgiving when the network does change."},
{t:"Dynamic routing protocol",a:"",d:"Networking & Protocols",def:"A protocol that lets routers learn paths by talking to their neighbours. Convenient, and a target — routing announcements can be forged."},
{t:"Exterior gateway protocol",a:"EGP",d:"Networking & Protocols",def:"A protocol that carries routing between separately administered networks rather than inside one. BGP is the one that survived."},
{t:"Gateway",a:"",d:"Networking & Protocols",def:"A network point that leads into another network. Your default gateway is the router you send everything you cannot reach directly to."},
{t:"Router",a:"",d:"Networking & Protocols",def:"A device that forwards traffic between networks based on IP addresses. It decides where a packet goes next, hop by hop."},
{t:"Filtering router",a:"",d:"Networking & Protocols",def:"A router that also decides whether a packet should be forwarded at all, according to policy. The simplest form of firewall."},
{t:"Standard ACL",a:"Cisco",d:"Networking & Protocols",def:"A router filter that makes its decision on source IP address alone. Blunt, but cheap to evaluate at line rate."},
{t:"Extended ACL",a:"Cisco",d:"Networking & Protocols",def:"A router filter that can also match destination, protocol, ports and whether a session is already established."},
{t:"Reflexive ACL",a:"Cisco",d:"Networking & Protocols",def:"A router filter that only allows return traffic belonging to connections started from inside. A step toward stateful firewalling."},
{t:"Stateful inspection",a:"Dynamic packet filtering",d:"Networking & Protocols",def:"Firewalling that tracks the state of each connection rather than judging every packet alone. It is how a firewall knows a reply is legitimate."},
{t:"Switch",a:"",d:"Networking & Protocols",def:"A device that learns which MAC address sits on which port and sends frames only where they need to go. It is why a modern LAN does not broadcast everything to everyone."},
{t:"Hub",a:"",d:"Networking & Protocols",def:"An obsolete device that repeated every incoming signal out of every port. Convenient for sniffing, which is exactly why switches replaced it."},
{t:"Spanning port",a:"Port mirroring, SPAN",d:"Networking & Protocols",def:"A switch port configured to receive a copy of other ports' traffic. How monitoring and intrusion detection get to see the network."},
{t:"Network tap",a:"",d:"Networking & Protocols",def:"A hardware device spliced into a cable that copies passing traffic to a monitoring system. Unlike a mirrored port, it cannot silently drop traffic under load."},
{t:"Promiscuous mode",a:"",d:"Networking & Protocols",def:"A network interface configured to accept every packet it sees, not just its own. Necessary for packet capture, and a hallmark of a sniffer."},
{t:"Sniffer",a:"",d:"Networking & Protocols",def:"A tool that reads traffic off a network interface. The same tool troubleshoots a network and harvests credentials from it."},
{t:"Sniffing",a:"Passive wiretapping",d:"Networking & Protocols",def:"Reading network traffic you were not the intended recipient of. Passive, silent, and the reason unencrypted protocols are indefensible."},
{t:"Wiretapping",a:"",d:"Networking & Protocols",def:"Monitoring and recording data moving between two points in a communication system. Passive wiretapping listens; active wiretapping alters."},
{t:"Eavesdropping",a:"",d:"Networking & Protocols",def:"Listening in on a conversation not meant for you. Often the first step, not the whole attack — what is overheard becomes the way in."},
{t:"Trunking",a:"",d:"Networking & Protocols",def:"Carrying traffic for several VLANs over one link between switches. Misconfigured trunks are how attackers hop between VLANs."},
{t:"Multiplexing",a:"",d:"Networking & Protocols",def:"Combining several signals onto one path so they can share a link. Every backbone circuit depends on it."},
{t:"Unicast",a:"",d:"Networking & Protocols",def:"Traffic from one host to one host. The ordinary case."},
{t:"Multicast",a:"",d:"Networking & Protocols",def:"Traffic from one host to a defined group of hosts. Efficient for streaming, and awkward to filter."},
{t:"Full duplex",a:"",d:"Networking & Protocols",def:"A link that carries traffic in both directions at the same time. Half duplex takes turns; collisions are a half-duplex problem."},
{t:"Ethernet",a:"IEEE 802.3",d:"Networking & Protocols",def:"The dominant LAN technology — the wiring, framing and access rules under nearly every wired network."},
{t:"Frame",a:"",d:"Networking & Protocols",def:"The unit of data on a local network segment, wrapping a packet in link-layer addressing. Frames carry packets the way envelopes carry letters."},
{t:"Header",a:"",d:"Networking & Protocols",def:"The extra information at the front of a packet that lets the protocol stack handle it — addresses, lengths, flags. Everything an inspection tool reads first."},
{t:"Fragmentation",a:"",d:"Networking & Protocols",def:"Splitting a packet into smaller pieces to fit a link's maximum size. A reliable source of security bugs, because reassembly is easy to get wrong."},
{t:"Fragment offset",a:"",d:"Networking & Protocols",def:"The field that says where a fragment belongs in the original packet. Forged offsets are how fragmentation attacks overwrite headers."},
{t:"Fragment overlap attack",a:"",d:"Networking & Protocols",def:"An attack that sends fragments with deliberately wrong offsets so reassembly overwrites part of the original header — for example, the destination port."},
{t:"Tiny fragment attack",a:"",d:"Networking & Protocols",def:"Splitting a packet so small that the fields a filter checks land in the second fragment, letting the first slip past the rule."},
{t:"Preamble",a:"",d:"Networking & Protocols",def:"The pattern of bits at the start of a transmission that lets receivers lock on to the timing. Below the level most people ever look at, and essential."},
{t:"Synchronisation",a:"",d:"Networking & Protocols",def:"The distinctive bit pattern network hardware watches for to know a frame is starting."},
{t:"Octet",a:"",d:"Networking & Protocols",def:"Eight bits. Used instead of 'byte' in networking, where a byte has not always meant eight bits."},
{t:"Netmask",a:"Subnet mask",d:"Networking & Protocols",def:"The 32-bit value that separates the network part of an address from the host part. It decides what counts as local and what has to go through a router."},
{t:"Sub network",a:"Subnet",d:"Networking & Protocols",def:"A separately identifiable slice of a bigger network, usually a building, a floor or a single LAN."},
{t:"Private addressing",a:"RFC 1918",d:"Networking & Protocols",def:"The address ranges reserved for internal networks — 10/8, 172.16/12 and 192.168/16 — which routers on the public internet will not carry."},
{t:"Loopback address",a:"127.0.0.1",d:"Networking & Protocols",def:"The pseudo-address that always means this machine. Traffic to it never leaves the host, which is why services bound to it are not exposed."},
{t:"IP forwarding",a:"",d:"Networking & Protocols",def:"The operating system setting that lets a host pass traffic between its network interfaces — that is, act as a router. Enabled accidentally, it bridges networks you meant to keep apart."},
{t:"IP spoofing",a:"",d:"Networking & Protocols",def:"Sending packets with a forged source address. It hides the sender, breaks address-based trust, and makes amplification attacks possible."},
{t:"Spoof",a:"",d:"Networking & Protocols",def:"Posing as someone or something else to gain access — an address, a sender name, a caller ID. The general case behind spoofing of every kind."},
{t:"Forward lookup",a:"",d:"Networking & Protocols",def:"Using a domain name to find its IP address. The ordinary DNS query."},
{t:"Reverse lookup",a:"PTR lookup",d:"Networking & Protocols",def:"Using an IP address to find the name behind it. Useful in investigations, and often stale or missing."},
{t:"gethostbyname / gethostbyaddr",a:"",d:"Networking & Protocols",def:"The classic pair of lookup calls: name to address, and address to name. The programming face of forward and reverse DNS."},
{t:"Fully-qualified domain name",a:"FQDN",d:"Networking & Protocols",def:"A hostname written out in full, all the way to the top-level domain — host plus complete domain, with nothing implied."},
{t:"Domain name",a:"",d:"Networking & Protocols",def:"The name that locates an organisation on the internet, read right to left from the top-level domain inward."},
{t:"Domain hijacking",a:"",d:"Networking & Protocols",def:"Taking control of someone's domain — through the registrar, the DNS servers, or an expired registration. Everything that trusts the name follows the attacker."},
{t:"Cache poisoning",a:"DNS poisoning",d:"Networking & Protocols",def:"Getting a name server to store and serve a false answer, so everyone it serves is quietly sent to the wrong place."},
{t:"DNS cache",a:"",d:"Networking & Protocols",def:"The store of recent answers a resolver keeps so it need not ask again. It makes DNS fast, and gives poisoning something to aim at."},
{t:"BGP hijacking",a:"Route hijacking",d:"Networking & Protocols",def:"Announcing routes for address space you do not own, pulling other people's traffic through your network. The internet's routing still runs largely on trust."},
{t:"Autonomous system number",a:"ASN",d:"Networking & Protocols",def:"The globally unique number identifying a network in the routing system. Useful in attribution: it says which network an address belongs to."},
{t:"WHOIS",a:"",d:"Networking & Protocols",def:"The lookup service for who registered a domain or holds a block of addresses. Redaction has hollowed it out, but it is still an early stop in an investigation."},
{t:"Proxy server",a:"",d:"Networking & Protocols",def:"A server that sits between users and the internet, fetching things on their behalf. It can filter, cache, log — and it hides the real client from the far end."},
{t:"Forward proxy",a:"",d:"Networking & Protocols",def:"A proxy that clients send their outbound requests through. The point where an organisation can inspect and control what leaves."},
{t:"HTTP proxy",a:"",d:"Networking & Protocols",def:"A proxy specifically for web traffic, sitting between browsers and servers. Also the standard tool for intercepting and modifying requests during testing."},
{t:"SOCKS",a:"",d:"Networking & Protocols",def:"A generic proxy protocol that forwards connections of any kind rather than just web traffic. Widely used to route traffic through somewhere else, legitimately or not."},
{t:"Tor",a:"The Onion Router",d:"Networking & Protocols",def:"A network that routes traffic through several volunteer relays, each knowing only the previous and next hop, so no single point sees both who you are and where you are going."},
{t:"Onion Router",a:"Tor",d:"Networking & Protocols",def:"The full name of Tor, filed here so it can be found under O as well as T. Traffic is wrapped in a layer of encryption for each relay it will cross, and each relay peels off one — hence the onion."},
{t:"Onion routing",a:"",d:"Networking & Protocols",def:"The layered-encryption technique behind Tor: each relay peels off one layer, learning only enough to pass the traffic on."},
{t:"Dark web",a:"",d:"Networking & Protocols",def:"Sites reachable only through anonymising networks like Tor. It hosts marketplaces and leak sites, and also censorship-resistant journalism."},
{t:"Geoblocking",a:"",d:"Networking & Protocols",def:"Allowing or refusing access based on the country an IP address maps to. Trivially bypassed with a VPN, which is why it filters noise rather than adversaries."},
{t:"Telnet",a:"",d:"Networking & Protocols",def:"A remote login protocol that sends everything, passwords included, in the clear. Replaced by SSH, and still found on forgotten devices."},
{t:"FTP",a:"File Transfer Protocol",d:"Networking & Protocols",def:"An old file transfer protocol that authenticates in the clear and needs awkward extra connections. Superseded by SFTP and HTTPS."},
{t:"POP3",a:"Post Office Protocol",d:"Networking & Protocols",def:"A mail protocol where the client downloads messages from the server, traditionally removing them. Largely displaced by IMAP."},
{t:"IMAP",a:"Internet Message Access Protocol",d:"Networking & Protocols",def:"A mail protocol that keeps messages on the server and syncs state across devices. What most mail clients speak today."},
{t:"SNMP",a:"Simple Network Management Protocol",d:"Networking & Protocols",def:"The protocol for monitoring and configuring network devices. Old versions used a shared community string as the only password — often left as 'public'."},
{t:"PPP",a:"Point-to-Point Protocol",d:"Networking & Protocols",def:"A protocol for carrying IP over a direct link between two machines, historically a dial-up line."},
{t:"PPTP",a:"Point-to-Point Tunneling Protocol",d:"Networking & Protocols",def:"An early VPN protocol, now considered broken. Its presence in a configuration is a finding, not a feature."},
{t:"L2TP",a:"Layer 2 Tunneling Protocol",d:"Networking & Protocols",def:"A tunnelling protocol used to build VPNs, normally paired with IPsec because it provides no encryption of its own."},
{t:"Token ring",a:"",d:"Networking & Protocols",def:"A LAN design where a circulating token granted the right to transmit, avoiding collisions by design. Elegant, and beaten by cheap Ethernet."},
{t:"Topology",a:"",d:"Networking & Protocols",def:"The shape of a network — bus, star, ring, mesh — physically or logically. Two networks can share a logical topology and look nothing alike in the racks."},
{t:"T1 / T3",a:"",d:"Networking & Protocols",def:"Traditional leased digital circuits of fixed capacity. Still a unit of thinking in telecoms, if rarely a purchase."},
{t:"Store-and-forward",a:"",d:"Networking & Protocols",def:"Switching where the whole packet is read and checked before being sent on. Slower than cut-through, and it does not forward corrupted frames."},
{t:"Cut-through",a:"",d:"Networking & Protocols",def:"Switching that starts forwarding as soon as the header is read, before the whole packet arrives. Lower latency, at the cost of passing on damaged frames."},
{t:"Crossover cable",a:"",d:"Networking & Protocols",def:"A cable wired to swap transmit and receive pairs so two devices can be connected directly. Modern hardware auto-detects, so it is mostly history."},
{t:"Straight-through cable",a:"",d:"Networking & Protocols",def:"An ordinary patch cable with each pin wired to the same pin at the other end."},
{t:"Multi-homed",a:"",d:"Networking & Protocols",def:"Connected to more than one upstream provider. It buys resilience, and it complicates routing and filtering."},
{t:"Internet",a:"",d:"Networking & Protocols",def:"Strictly, the practice of connecting separate networks together; in general use, the global network that resulted."},
{t:"Intranet",a:"",d:"Networking & Protocols",def:"An organisation's own internal network built on internet technology, closed to outsiders."},
{t:"Internet Standard",a:"",d:"Networking & Protocols",def:"A specification the IETF has blessed as stable, well understood and proven by working implementations."},
{t:"RFC",a:"Request for Comments",d:"Networking & Protocols",def:"The numbered document series in which internet protocols are proposed and defined. Anyone can submit one; the IETF decides what becomes a standard."},
{t:"IETF",a:"Internet Engineering Task Force",d:"Networking & Protocols",def:"The body that defines the internet's operating protocols, through open working groups and RFCs."},
{t:"ARPANET",a:"",d:"Networking & Protocols",def:"The 1970s packet-switched research network, funded by the US government, that the internet grew out of. Decommissioned in 1990."},
{t:"OSI model",a:"Open Systems Interconnection",d:"Networking & Protocols",def:"The seven-layer reference model for network communication, from physical wiring up to the application. Nothing implements it exactly; everyone uses it to describe where a problem sits."},
{t:"Protocol stack",a:"",d:"Networking & Protocols",def:"The set of protocol layers that work together to move data, each handing off to the one below."},
{t:"Protocol",a:"",d:"Networking & Protocols",def:"An agreed set of rules for how two endpoints communicate. Protocols exist at every layer of a connection."},
{t:"TCP/IP",a:"Internet Protocol Suite",d:"Networking & Protocols",def:"The protocol family the internet runs on, named for its two central members. Also usable on a private network."},
{t:"Segment",a:"",d:"Networking & Protocols",def:"A TCP packet. Also, confusingly, a physical or logical slice of a network."},
{t:"SYN flood",a:"",d:"Networking & Protocols",def:"A denial of service that opens half-finished TCP handshakes faster than the target can clear them, exhausting its connection table."},
{t:"Smurf",a:"",d:"Networking & Protocols",def:"An old amplification attack: ping a network's broadcast address with the victim's address forged as the source, and every host replies to the victim."},
{t:"Flooding",a:"",d:"Networking & Protocols",def:"Overwhelming a system with more input than it can process. The mechanism under most denial of service."},
{t:"Resource exhaustion",a:"",d:"Networking & Protocols",def:"Tying up something finite — memory, connections, file handles, disk — until there is none left for legitimate use."},
{t:"Overload",a:"",d:"Networking & Protocols",def:"Degrading a system by loading it beyond what its components can handle. The result may be denial of service without any exploit at all."},
{t:"Exponential backoff",a:"",d:"Networking & Protocols",def:"Waiting progressively longer between retries after a failure, so a struggling system is not hammered by everything retrying at once."},
{t:"Windowing",a:"",d:"Networking & Protocols",def:"A windowing system shares a screen among several running applications, tracking where each window is and what state it is in."},
{t:"Non-printable character",a:"",d:"Networking & Protocols",def:"A byte with no visible character, like a linefeed or a null. Filters that only think about visible text are routinely bypassed with these."},
/* --- Cryptography (added) --- */
{t:"Cipher",a:"",d:"Cryptography",def:"An algorithm for turning readable text into unreadable text and back. The cipher is public; the key is what must stay secret."},
{t:"Block cipher",a:"",d:"Cryptography",def:"A cipher that encrypts fixed-size blocks of data at a time. AES is the one in use nearly everywhere."},
{t:"Stream cipher",a:"",d:"Cryptography",def:"A cipher that encrypts data continuously, a bit or byte at a time, rather than in blocks. Fast, and unforgiving if a keystream is ever reused."},
{t:"Cryptanalysis",a:"",d:"Cryptography",def:"The science of breaking cryptography — recovering plaintext or keys without being given them. What a cipher has to survive to be trusted."},
{t:"Symmetric key",a:"",d:"Cryptography",def:"One key used for both encryption and decryption. Fast, and it leaves you with the problem of getting the key to the other side."},
{t:"Public key",a:"",d:"Cryptography",def:"The half of a key pair you can publish. Others encrypt to it or verify signatures with it; only the private half can reverse that."},
{t:"Public key encryption",a:"Asymmetric cryptography",d:"Cryptography",def:"Encryption with a key pair, where what one key does only the other can undo. It solves key distribution at the cost of speed."},
{t:"Hybrid encryption",a:"",d:"Cryptography",def:"Using asymmetric cryptography to agree a key and symmetric cryptography to encrypt the data. Every TLS connection works this way."},
{t:"Session key",a:"",d:"Cryptography",def:"A symmetric key used for a single connection or a short period, then discarded. Limits how much traffic one compromised key exposes."},
{t:"Split key",a:"",d:"Cryptography",def:"A key divided into parts, none of which reveals anything alone. Used where no one person should be able to act by themselves."},
{t:"Digital envelope",a:"",d:"Cryptography",def:"A message encrypted with a session key, packaged together with that session key encrypted to the recipient. The classic hybrid construction."},
{t:"One-way function",a:"",d:"Cryptography",def:"A function easy to compute forwards and infeasible to reverse. The foundation of hashing and of public-key cryptography."},
{t:"One-way encryption",a:"",d:"Cryptography",def:"An irreversible transformation, where the original cannot be recovered from the output even knowing the key. Hashing, not encryption, despite the name."},
{t:"Checksum",a:"",d:"Cryptography",def:"A short value computed from data and stored with it, to detect whether the data changed. It catches accidents, not attackers."},
{t:"Cyclic redundancy check",a:"CRC",d:"Cryptography",def:"A checksum designed to catch transmission errors. Fast, standard, and trivially forged — never use it as a security control."},
{t:"MD5",a:"",d:"Cryptography",def:"An old cryptographic hash, now broken: attackers can produce two inputs with the same digest. Still seen as a file identifier, never as a security control."},
{t:"SHA-1",a:"",d:"Cryptography",def:"A superseded hash function with demonstrated collisions. Anything still relying on it for signatures is a finding."},
{t:"Triple DES",a:"3DES",d:"Cryptography",def:"DES applied three times to compensate for its short key. Slow, deprecated, and still lurking in payment and legacy systems."},
{t:"DES",a:"Data Encryption Standard",d:"Cryptography",def:"The 1970s US encryption standard, retired because its 56-bit key can be brute-forced. Its successor is AES."},
{t:"Permutation",a:"",d:"Cryptography",def:"Rearranging the positions of characters or bits rather than replacing them. One of the two classical building blocks of ciphers, with substitution."},
{t:"Steganalysis",a:"",d:"Cryptography",def:"Detecting and defeating steganography — finding the hidden message rather than reading an encrypted one."},
{t:"Digital Signature Algorithm",a:"DSA",d:"Cryptography",def:"An asymmetric algorithm that produces signatures as a pair of large numbers. Verifies both who signed and that nothing changed."},
{t:"PGP",a:"Pretty Good Privacy",d:"Cryptography",def:"Long-standing software for encrypting and signing mail and files with public keys. Powerful, awkward, and still the standard in some communities."},
{t:"Web of trust",a:"",d:"Cryptography",def:"Trust built by people signing each other's keys, rather than granted by a central authority. PGP's alternative to certificate authorities."},
{t:"S/Key",a:"",d:"Cryptography",def:"An early one-time password scheme that generates a chain of passwords by repeated hashing. The ancestor of modern OTP."},
{t:"Digest authentication",a:"",d:"Cryptography",def:"A web authentication scheme where the client proves it knows the password by hashing a challenge, rather than sending the password itself."},
{t:"Basic authentication",a:"",d:"Cryptography",def:"The simplest web authentication: the username and password are sent with every request, barely encoded. Safe only inside TLS, and not really then."},
{t:"Certificate-based authentication",a:"",d:"Cryptography",def:"Proving identity with a certificate and its private key instead of a password. Phishing-resistant, and only as good as the issuing process."},
{t:"Public-key forward secrecy",a:"PFS",d:"Cryptography",def:"The property that recording today's traffic gains nothing if a long-term private key leaks later, because session keys are derived fresh."},
{t:"Emanations analysis",a:"TEMPEST",d:"Cryptography",def:"Reading data from the unintentional signals a device gives off — electromagnetic leakage, sound, power draw. Defended by shielding, not software."},
{t:"Signals analysis",a:"",d:"Cryptography",def:"Deriving information indirectly from a signal a system emits that was never meant to carry it."},
{t:"Radiation monitoring",a:"",d:"Cryptography",def:"Capturing images, data or audio by listening to the radiation an unshielded device emits."},
/* --- Identity & Access (added) --- */
{t:"Access management",a:"",d:"Identity & Access",def:"The everyday work of keeping access information correct: creating accounts, maintaining them, watching them, and revoking them when they should end."},
{t:"Access control service",a:"",d:"Identity & Access",def:"A service whose job is to keep unauthorised users away from system resources, usually through lists of permitted identities or issued tickets."},
{t:"Authenticity",a:"",d:"Identity & Access",def:"That information is genuine and unaltered — that it really is what it claims to be."},
{t:"Discretionary access control",a:"DAC",d:"Identity & Access",def:"Access decided by the owner of the resource, who can hand out permissions at will. Flexible, and it drifts."},
{t:"Mandatory access control",a:"MAC",d:"Identity & Access",def:"Access decided by the system from classification labels on both users and data, which users cannot override. The model behind government classification."},
{t:"Role-based access control",a:"RBAC (concept)",d:"Identity & Access",def:"Access granted through roles that match job functions, rather than to individuals one at a time."},
{t:"Rule set based access control",a:"RSBAC",d:"Identity & Access",def:"Access decided by rules about what entities may do to objects, rather than by lists attached to either."},
{t:"List based access control",a:"",d:"Identity & Access",def:"Access defined by attaching a list of users and privileges to each object."},
{t:"Token-based access control",a:"",d:"Identity & Access",def:"Access defined by attaching a list of objects and privileges to each user — the mirror image of list-based control."},
{t:"Token-based device",a:"Hardware token",d:"Identity & Access",def:"A device that generates a changing code the user must supply to log in, proving they physically hold it."},
{t:"Lattice techniques",a:"",d:"Identity & Access",def:"Access decided by ordered security labels, where information may move in one direction through the ordering but not the other."},
{t:"Simple security property",a:"No read up",d:"Identity & Access",def:"In Bell-LaPadula, a user may not read data classified higher than their own clearance."},
{t:"Star property",a:"No write down",d:"Identity & Access",def:"In Bell-LaPadula, a user may not write data down to a lower classification, which would leak it."},
{t:"Strong star property",a:"",d:"Identity & Access",def:"A stricter rule: a user may write only at their own level, neither up nor down."},
{t:"Simple integrity property",a:"No write up",d:"Identity & Access",def:"In the Biba integrity model, a user may not write data to a higher integrity level than their own."},
{t:"Integrity star property",a:"No read down",d:"Identity & Access",def:"In the Biba integrity model, a user may not read data of lower integrity than their own, which would contaminate their work."},
{t:"Biometrics",a:"",d:"Identity & Access",def:"Authenticating people by physical characteristics — fingerprint, face, iris. Convenient, and impossible to reissue once copied."},
{t:"False rejects",a:"",d:"Identity & Access",def:"When an authentication system turns away a legitimate user. Tuning a system to reduce false accepts almost always raises these."},
{t:"Smartcard",a:"",d:"Identity & Access",def:"A card with a chip that holds keys and performs cryptographic operations without releasing them. The basis of most government credentialing."},
{t:"Identity",a:"",d:"Identity & Access",def:"Who someone or what something is — the name by which a system knows them. Everything an access decision rests on."},
{t:"Escrow passwords",a:"",d:"Identity & Access",def:"Passwords written down and locked away so emergency staff can get in when the usual people are unavailable. A control that has to be audited, not forgotten."},
{t:"Shadow password file",a:"",d:"Identity & Access",def:"The separate, restricted file where Unix stores password hashes, so ordinary users cannot read them out of the world-readable account file."},
{t:"Password cracking",a:"",d:"Identity & Access",def:"Working out passwords from stolen hashes by guessing and hashing candidates until one matches."},
{t:"Dictionary attack",a:"",d:"Identity & Access",def:"Trying words and phrases from a prepared list rather than every possible combination. Faster than brute force, because people pick words."},
{t:"Hybrid attack",a:"",d:"Identity & Access",def:"A dictionary attack that also tries the predictable variations people add — numbers, symbols, capital first letters."},
{t:"Password sniffing",a:"",d:"Identity & Access",def:"Capturing credentials off the wire, usually on a local network, from protocols that send them in the clear."},
{t:"PAP",a:"Password Authentication Protocol",d:"Identity & Access",def:"A weak authentication scheme that sends the password across the network, usually unprotected. Superseded by CHAP and everything after."},
{t:"CHAP",a:"Challenge-Handshake Authentication Protocol",d:"Identity & Access",def:"Authentication by responding to a fresh challenge each time, so a captured response cannot be replayed."},
{t:"EAP",a:"Extensible Authentication Protocol",d:"Identity & Access",def:"A framework that lets a link negotiate which authentication method to use, from passwords to certificates. The basis of enterprise Wi-Fi authentication."},
{t:"Form-based authentication",a:"",d:"Identity & Access",def:"Logging in through a web page form rather than a browser or protocol mechanism. What almost every web application does, with all the session handling that implies."},
{t:"Null session",a:"Anonymous logon",d:"Identity & Access",def:"A Windows connection made without credentials that could still enumerate users and shares. A classic reconnaissance foothold."},
{t:"Root",a:"",d:"Identity & Access",def:"The all-powerful administrative account on Unix systems. Gaining it is usually the attacker's objective, not their entry point."},
{t:"Trust",a:"",d:"Identity & Access",def:"In systems terms, the relationship that decides what one machine or domain will let another's users do."},
{t:"Forest",a:"",d:"Identity & Access",def:"A set of Active Directory domains that replicate with each other. The boundary that matters when working out how far a compromise can reach."},
{t:"Domain",a:"Windows domain",d:"Identity & Access",def:"A set of network resources and accounts managed together, where users log in once to reach everything in it."},
{t:"Directory",a:"",d:"Identity & Access",def:"The catalogue of users, groups, machines and their attributes that an organisation authenticates against."},
{t:"LDAP",a:"Lightweight Directory Access Protocol",d:"Identity & Access",def:"The protocol for querying a directory of users, groups and resources. Directory queries are also how attackers map an organisation from the inside."},
/* --- Attacks & Exploitation (added) --- */
{t:"Account harvesting",a:"",d:"Attacks & Exploitation",def:"Collecting the valid account names on a system. Half of a password attack is knowing who exists."},
{t:"ACK piggybacking",a:"",d:"Attacks & Exploitation",def:"Sending an acknowledgement inside another packet already headed the same way, rather than on its own."},
{t:"Asymmetric warfare",a:"",d:"Attacks & Exploitation",def:"Conflict where a small investment, well aimed, produces effects out of all proportion to its cost. The standing description of offensive cyber."},
{t:"Stack mashing",a:"",d:"Attacks & Exploitation",def:"Using a buffer overflow to overwrite the stack so the program returns into attacker-supplied code."},
{t:"Cache cramming",a:"",d:"Attacks & Exploitation",def:"Tricking a browser into running cached code from local disk, where it is granted more permission than code from the internet would get."},
{t:"Covert channel",a:"",d:"Attacks & Exploitation",def:"A way to move information using system behaviour never meant to carry it — free disk space, timing, packet sizes. Hard to see and harder to stop."},
{t:"Defacement",a:"",d:"Attacks & Exploitation",def:"Altering a website's content to embarrass or make a point. Loud by design, and often a cover for something quieter."},
{t:"Denial of service",a:"DoS (concept)",d:"Attacks & Exploitation",def:"Preventing legitimate access to a system, or delaying it enough to matter. It does not require breaking in."},
{t:"Dumpster diving",a:"",d:"Attacks & Exploitation",def:"Finding passwords, directories and documents in what an organisation threw away. Shredding is a security control."},
{t:"Fault line attack",a:"",d:"Attacks & Exploitation",def:"Exploiting the gaps between systems, where each side assumes the other is checking. Integration points are where coverage runs out."},
{t:"Fork bomb",a:"",d:"Attacks & Exploitation",def:"A process that repeatedly copies itself until no process slots remain and the machine stops. Four characters of shell, and a hard lesson in resource limits."},
{t:"Hijack attack",a:"",d:"Attacks & Exploitation",def:"Seizing control of an already-established connection, so the attacker inherits an authenticated session."},
{t:"Inference attack",a:"",d:"Attacks & Exploitation",def:"Deriving something sensitive by connecting pieces of information that are individually harmless. The problem statistical disclosure control exists to solve."},
{t:"Input validation attack",a:"",d:"Attacks & Exploitation",def:"Deliberately sending unexpected input to see what breaks. The parent class of injection, overflow and traversal bugs."},
{t:"Masquerade attack",a:"",d:"Attacks & Exploitation",def:"One entity illegitimately posing as another to gain what that identity is trusted with."},
{t:"Penetration",a:"",d:"Attacks & Exploitation",def:"Getting unauthorised access to sensitive data by getting around a system's protections."},
{t:"Pharming",a:"",d:"Attacks & Exploitation",def:"Redirecting users to a fake site by corrupting name resolution, so the address they typed is correct and the destination is not."},
{t:"Scavenging",a:"",d:"Attacks & Exploitation",def:"Searching through leftover data — deleted files, swap space, freed memory — for something sensitive that was never really erased."},
{t:"War dialing",a:"",d:"Attacks & Exploitation",def:"Dialling ranges of telephone numbers to find modems answering. The ancestor of port scanning."},
{t:"War driving",a:"",d:"Attacks & Exploitation",def:"Driving around looking for wireless networks that can be reached or joined."},
{t:"War chalking",a:"",d:"Attacks & Exploitation",def:"Marking pavements to show where open wireless signals could be picked up. A period detail from the early Wi-Fi years."},
{t:"Smishing",a:"",d:"Attacks & Exploitation",def:"Phishing over SMS rather than email. Short messages strip away most of the cues people use to spot a fake."},
{t:"Vishing",a:"Voice phishing",d:"Attacks & Exploitation",def:"Phishing by phone call, including over VoIP. Now routinely paired with cloned voices."},
{t:"Competitive intelligence",a:"",d:"Attacks & Exploitation",def:"Gathering information about competitors by means that are legal, or at least not obviously illegal. The boundary with espionage is thinner than the phrase suggests."},
{t:"Reverse engineering",a:"",d:"Attacks & Exploitation",def:"Working out how a system or component functions by taking it apart. Used to find vulnerabilities, to analyse malware, and to steal designs."},
{t:"Disassembly",a:"",d:"Attacks & Exploitation",def:"Turning a compiled binary back into assembly to see what it actually does. The starting point of most malware analysis."},
{t:"Tamper",a:"",d:"Attacks & Exploitation",def:"Deliberately altering a system's logic, data or control information so it does something it should not."},
{t:"Corruption",a:"",d:"Attacks & Exploitation",def:"A threat action that changes system functions or data so the system works wrongly rather than not at all."},
{t:"Disruption",a:"",d:"Attacks & Exploitation",def:"An event that interrupts or prevents correct operation of a service. It need not be an attack — a cut cable counts."},
{t:"Exposure",a:"",d:"Attacks & Exploitation",def:"A threat action where sensitive data is released directly to someone not entitled to it."},
/* --- Malware & Threat Actors (added) --- */
{t:"Sandworm",a:"",d:"Malware & Threat Actors",def:"The Russian military intelligence unit behind BlackEnergy, Industroyer, NotPetya and the attacks that cut power in Ukraine. The name comes from Andy Greenberg's book about it — the standard case study in cyber as an instrument of war."},
{t:"Sandbox",a:"",d:"Malware & Threat Actors",def:"An isolated environment where untrusted code can run without touching anything that matters — a browser tab, a malware analysis VM, or the boundary an AI agent is meant to stay inside. Only as strong as the boundary itself: escapes are the whole game."},
{t:"Sandbox escape",a:"",d:"Malware & Threat Actors",def:"Breaking out of the isolation a sandbox is supposed to enforce, so code reaches the host, the network, or credentials it was never meant to see."},
{t:"Malicious code",a:"",d:"Malware & Threat Actors",def:"Software that looks useful but takes unauthorised access, or tricks the user into running something worse. The umbrella over viruses, Trojans and the rest."},
{t:"Crimeware",a:"",d:"Malware & Threat Actors",def:"Malware built to make its operator money — stealing keystrokes, draining accounts, renting out infected machines."},
{t:"Boot record infector",a:"",d:"Malware & Threat Actors",def:"Malware that writes itself into the boot sector so it runs before the operating system does. The predecessor of the modern bootkit."},
{t:"Program infector",a:"",d:"Malware & Threat Actors",def:"Malware that attaches itself to existing executables, so running an ordinary program runs it too."},
{t:"Polymorphism",a:"",d:"Malware & Threat Actors",def:"Malware that rewrites its own code as it spreads, so no two copies look alike to a signature scanner."},
{t:"Stealthing",a:"",d:"Malware & Threat Actors",def:"The techniques malicious code uses to hide the fact that it is present on an infected system."},
{t:"Fast flux",a:"",d:"Malware & Threat Actors",def:"Rapidly rotating the addresses a domain resolves to, across a botnet, so the infrastructure behind it cannot be taken down by blocking an IP."},
{t:"Zombie",a:"",d:"Malware & Threat Actors",def:"A compromised machine taking orders remotely, usually as one of many in a botnet. Its owner almost never knows."},
{t:"Morris Worm",a:"",d:"Malware & Threat Actors",def:"The 1988 worm that spread across the ARPANET and forced thousands of hosts offline. The event that produced the first CERT."},
{t:"QAZ",a:"",d:"Malware & Threat Actors",def:"A network worm from around 2000, notable mainly as an early case of a backdoor spreading through file shares."},
{t:"Honey pot",a:"",d:"Malware & Threat Actors",def:"A system that exists only to be attacked, so defenders can watch how it is attacked. Anything touching it is suspicious by definition."},
{t:"Honeymonkey",a:"Honey client",d:"Malware & Threat Actors",def:"An automated system that browses the web pretending to be a user, to find sites that attack visitors."},
{t:"Monoculture",a:"",d:"Malware & Threat Actors",def:"Everyone running the same software, so one vulnerability reaches everyone. A resilience argument, not a technical one."},
{t:"DPRK IT worker scheme",a:"North Korean remote workers",d:"Malware & Threat Actors",def:"North Korean operatives hired as remote IT staff under bought or stolen identities, routing pay back to the state and leaving remote access behind. Detected through identity, payroll and geolocation anomalies as much as through malware."},
{t:"CRINK",a:"China, Russia, Iran, North Korea",d:"Malware & Threat Actors",def:"Shorthand for the four states most often named as the strategic cyber adversaries of the United States and its allies. Convenient, and it flattens four very different actors."},
/* --- Defense & Operations (added) --- */
{t:"Auditing",a:"",d:"Defense & Operations",def:"Gathering and examining evidence about systems to check they comply with policy and are not exposed. The routine, unglamorous half of assurance."},
{t:"Activity monitor",a:"",d:"Defense & Operations",def:"A defence that watches for malicious behaviour on a system and blocks it as it happens, rather than matching known files."},
{t:"Countermeasure",a:"",d:"Defense & Operations",def:"An action taken to stop a detected threat from succeeding — a patch, a block rule, a filter."},
{t:"Intrusion detection",a:"IDS (concept)",d:"Defense & Operations",def:"Gathering and analysing activity across a system or network to spot security breaches, whether from outside or from insiders."},
{t:"Host-based intrusion detection",a:"HIDS",d:"Defense & Operations",def:"Detection that works from a single machine's own records — audit logs, file changes, process activity. Deep visibility on one host, blind to the rest."},
{t:"Network-based intrusion detection",a:"NIDS",d:"Defense & Operations",def:"Detection that watches traffic passing a sensor on the network. It sees breadth, and only what crosses its own segment."},
{t:"Signature (detection)",a:"",d:"Defense & Operations",def:"A distinctive pattern that identifies a specific tool or exploit in traffic or on disk. Precise, and useless against anything new."},
{t:"Stimulus and response",a:"",d:"Defense & Operations",def:"In traffic analysis, the distinction between packets that start something and packets that answer. Unsolicited responses are a signal worth chasing."},
{t:"Egress filtering",a:"",d:"Defense & Operations",def:"Filtering traffic leaving your network. Ignored for years, and one of the most effective ways to break command and control."},
{t:"Ingress filtering",a:"",d:"Defense & Operations",def:"Filtering traffic entering your network, including dropping packets whose source addresses could not legitimately come from outside."},
{t:"Filter",a:"",d:"Defense & Operations",def:"A rule deciding which packets are kept, shown or blocked — in a capture tool, in a firewall, or in a detection pipeline."},
{t:"Personal firewall",a:"",d:"Defense & Operations",def:"A firewall running on an individual machine rather than at the network boundary. The last control still standing once an attacker is already inside."},
{t:"Configuration management",a:"",d:"Defense & Operations",def:"Establishing a known-good baseline and keeping systems to it. Most incidents start with something that drifted."},
{t:"Incident handling",a:"",d:"Defense & Operations",def:"The plan for dealing with an incident, conventionally in six steps: preparation, identification, containment, eradication, recovery and lessons learned."},
{t:"Jump bag",a:"Go bag",d:"Defense & Operations",def:"The kit an incident responder can pick up and leave with — write blockers, drives, cables, notebooks, contact lists. Assembled before it is needed, not during."},
{t:"Event",a:"",d:"Defense & Operations",def:"Any observable occurrence on a system or network. Most events are nothing; an incident is an event that turns out to matter."},
{t:"Incident",a:"",d:"Defense & Operations",def:"An adverse event affecting a system or network, or a credible threat that one is about to happen."},
{t:"Incremental backup",a:"",d:"Defense & Operations",def:"A backup covering only what changed since the last one. Cheap to take, slower to restore, and useless if any link in the chain is missing."},
{t:"Log clipping",a:"",d:"Defense & Operations",def:"Selectively deleting entries from a log to hide a compromise. Why logs are shipped off the host as they are written."},
{t:"Syslog",a:"",d:"Defense & Operations",def:"The long-standing Unix logging facility, and the protocol for shipping those logs elsewhere. Still the plumbing under most log pipelines."},
{t:"Security log",a:"",d:"Defense & Operations",def:"The record of security-relevant activity on a system — logons, privilege use, policy changes. The first thing an investigator asks for and the first thing an attacker edits."},
{t:"TCP wrapper",a:"",d:"Defense & Operations",def:"An old but instructive control that decides whether to accept a connection to a service based on where it came from."},
{t:"TCPDump",a:"",d:"Defense & Operations",def:"The standard command-line packet capture tool on Unix. Windump is the Windows equivalent."},
{t:"Deception technology (honeytoken)",a:"",d:"Defense & Operations",def:"Planting credentials, files or hosts that have no legitimate use, so any touch is a high-confidence alert."},
{t:"Business impact analysis",a:"BIA",d:"Defense & Operations",def:"Working out how much disruption to each system the organisation can actually tolerate. It is what turns recovery targets from guesses into decisions."},
{t:"Cold, warm and hot sites",a:"Recovery sites",d:"Defense & Operations",def:"The three grades of standby facility. A hot site can take over in minutes and costs accordingly; a warm site takes hours to days; a cold site is space and power waiting for hardware to arrive."},
{t:"Contingency plan",a:"User contingency plan",d:"Defense & Operations",def:"How the business keeps working while the systems are down. Written for the people doing the work, not for the IT department."},
{t:"Natural disaster",a:"",d:"Defense & Operations",def:"Fire, flood, earthquake, storm — the causes of outage that no amount of patching prevents. They belong in the same plan as attacks."},
{t:"Insider threat programme",a:"",d:"Defense & Operations",def:"The formal function for spotting and handling harm caused by people with legitimate access. It sits across HR, legal and security, which is why it is hard to run."},
{t:"Enterprise risk management",a:"ERM",d:"Defense & Operations",def:"Looking at all of an organisation's risks together — cyber, financial, legal, physical — rather than in separate columns. Cyber stops being a special case."},
{t:"DLP monitoring",a:"DLP (practice)",d:"Defense & Operations",def:"Tooling that watches documents, mail and endpoints for sensitive information leaving, and blocks or flags it. Effective and intrusive: it means monitoring people's communications, which is a policy question before it is a technical one."},
{t:"Critical infrastructure",a:"",d:"Defense & Operations",def:"The sectors a country cannot function without — power, water, health, finance, transport, communications. Mostly privately owned, which is why defending it needs public-private arrangements."},
{t:"Left of boom / right of boom",a:"",d:"Defense & Operations",def:"Military shorthand adopted by security: everything before the incident is left of boom, everything after is right of boom. Prevention against response, on one timeline."},
/* --- Governance, Risk & Compliance (added) --- */
{t:"Confidentiality",a:"",d:"Governance, Risk & Compliance",def:"That information is seen only by those authorised to see it. The first leg of the CIA triad."},
{t:"Integrity",a:"",d:"Governance, Risk & Compliance",def:"That information has not been changed, by accident or design, and is complete and accurate."},
{t:"Availability",a:"",d:"Governance, Risk & Compliance",def:"That the system can actually do its job for the people who need it. The leg of the triad security controls most often damage."},
{t:"Possession",a:"",d:"Governance, Risk & Compliance",def:"Holding and controlling information, whether or not you can read it. A stolen encrypted laptop is a loss of possession even if confidentiality holds."},
{t:"Safety",a:"",d:"Governance, Risk & Compliance",def:"That the people involved with an organisation — staff, customers, visitors — come to no harm. In OT and medical systems it outranks every other property."},
{t:"Due care",a:"",d:"Governance, Risk & Compliance",def:"Putting a reasonable level of protection in place, in line with what the industry considers normal practice."},
{t:"Risk assessment",a:"",d:"Governance, Risk & Compliance",def:"Identifying what could go wrong and how much it would cost you. The input to every decision about what to spend."},
{t:"Risk averse",a:"",d:"Governance, Risk & Compliance",def:"Avoiding risk even at the price of the opportunity. A defensible position, and an expensive one when it becomes the default answer."},
{t:"Cost benefit analysis",a:"",d:"Governance, Risk & Compliance",def:"Weighing what a control costs against the risk it removes. The argument that gets security funded, or does not."},
{t:"Security policy",a:"",d:"Governance, Risk & Compliance",def:"The rules that say how an organisation protects its systems and information. Everything else — standards, procedures, controls — hangs off it."},
{t:"Program policy",a:"",d:"Governance, Risk & Compliance",def:"The high-level policy that sets the organisation's overall security posture and tone."},
{t:"Issue-specific policy",a:"",d:"Governance, Risk & Compliance",def:"A policy covering one particular subject, such as passwords or acceptable use."},
{t:"System-specific policy",a:"",d:"Governance, Risk & Compliance",def:"A policy written for one system or device, where general rules are not specific enough to act on."},
{t:"Separation of duties",a:"",d:"Governance, Risk & Compliance",def:"Splitting a sensitive task so no one person can complete it alone. It turns fraud from a decision into a conspiracy."},
{t:"Threat assessment",a:"",d:"Governance, Risk & Compliance",def:"Working out which kinds of threat an organisation is actually exposed to, before designing anything to stop them."},
{t:"Threat vector",a:"",d:"Governance, Risk & Compliance",def:"The route a threat takes to reach its target — email, a supplier, a remote service, a person."},
{t:"Information warfare",a:"",d:"Governance, Risk & Compliance",def:"The contest between attackers and defenders over information itself: taking it, corrupting it, denying it, or shaping what people believe."},
{t:"Measures of effectiveness",a:"MOE",d:"Governance, Risk & Compliance",def:"An attempt to estimate what effect a given action will actually have, rather than whether it was carried out."},
{t:"ISO",a:"International Organization for Standardization",d:"Governance, Risk & Compliance",def:"The international standards body whose members are national standards organisations. Its 27000 series covers information security management."},
{t:"ITU-T",a:"",d:"Governance, Risk & Compliance",def:"The United Nations telecommunications standards body, whose specifications are published as Recommendations. X.509 certificates come from here."},
{t:"NIST",a:"National Institute of Standards and Technology",d:"Governance, Risk & Compliance",def:"The US standards agency whose publications — the Cybersecurity Framework, the 800 series — function as default security guidance far beyond the US government."},
{t:"British Standard 7799",a:"BS 7799",d:"Governance, Risk & Compliance",def:"The British code of practice for information security management that became ISO/IEC 17799 and then ISO/IEC 27002."},
{t:"Executive order",a:"",d:"Governance, Risk & Compliance",def:"A directive from the US President binding on the executive branch. Much US cybersecurity policy — incident reporting, software supply chain requirements, critical infrastructure duties — arrives this way rather than through legislation."},
{t:"Title 18",a:"",d:"Governance, Risk & Compliance",def:"The part of the US Code covering federal crimes, including the computer fraud and wiretap statutes that most cyber prosecutions are brought under."},
{t:"Chatham House Rule",a:"",d:"Governance, Risk & Compliance",def:"A meeting convention: you may use what was said, but never say who said it. Standard for intelligence and industry threat-sharing sessions."},
{t:"Proprietary information",a:"",d:"Governance, Risk & Compliance",def:"Information unique to a company and central to its ability to compete — customer lists, costs, designs, trade secrets."},
{t:"Sensitive information",a:"",d:"Governance, Risk & Compliance",def:"Information that is not classified but would still cause harm if it got out. Governments define it formally; most organisations discover the definition after a leak."},
{t:"Data owner",a:"",d:"Governance, Risk & Compliance",def:"The person accountable for a set of data — what it is for, who may see it, how long it is kept. Accountability, not custody."},
{t:"Data custodian",a:"",d:"Governance, Risk & Compliance",def:"Whoever is currently holding or processing the data and is responsible for protecting it while they do. The database team is a custodian, not an owner."},
{t:"Data aggregation",a:"",d:"Governance, Risk & Compliance",def:"Combining several kinds of record to build a fuller picture than any of them gives alone. It is why individually harmless datasets can become sensitive together."},
{t:"Data mining",a:"",d:"Governance, Risk & Compliance",def:"Analysing existing data to find patterns worth acting on. The same technique serves fraud detection and intrusive profiling."},
{t:"Data warehousing",a:"",d:"Governance, Risk & Compliance",def:"Consolidating separate databases into one place for analysis. It also concentrates the consequences of one breach."},
{t:"Polyinstantiation",a:"",d:"Governance, Risk & Compliance",def:"Letting a database hold several records with the same key at different classification levels, so users at a lower level cannot infer that a higher-level record exists."},
{t:"Jitter (data)",a:"",d:"Governance, Risk & Compliance",def:"Perturbing values in a database while preserving its aggregate statistics, so individuals cannot be picked out of published data."},
/* --- Endpoints & Systems (added) --- */
{t:"Algorithm",a:"",d:"Endpoints & Systems",def:"A finite set of steps for solving a problem or performing a computation."},
{t:"Bit",a:"",d:"Endpoints & Systems",def:"The smallest unit of storage: a single 0 or 1."},
{t:"Byte",a:"",d:"Endpoints & Systems",def:"The smallest individually addressable unit of storage, in practice eight bits."},
{t:"Logic gate",a:"",d:"Endpoints & Systems",def:"The elementary building block of a digital circuit, taking binary inputs to a binary output. Everything above it is built from these."},
{t:"Daemon",a:"",d:"Endpoints & Systems",def:"A program that starts at boot and runs continuously in the background, serving requests. Windows calls the equivalent a service."},
{t:"Inetd",a:"xinetd",d:"Endpoints & Systems",def:"The old Unix service that listened on many ports and started the right program when a connection arrived."},
{t:"Shell",a:"",d:"Endpoints & Systems",def:"The command interpreter you type into — bash, zsh, PowerShell. Getting one on a target machine is the usual definition of a foothold."},
{t:"Unix",a:"",d:"Endpoints & Systems",def:"The multi-user, multitasking operating system from Bell Labs in the early 1970s whose design underlies Linux, macOS and most servers."},
{t:"GNU",a:"",d:"Endpoints & Systems",def:"The free software project started in 1983 to build a complete Unix-like system, whose tools sit under most Linux distributions."},
{t:"Loadable kernel module",a:"LKM",d:"Endpoints & Systems",def:"Code that adds functionality to a running kernel without a reboot. A useful facility, and how kernel-level rootkits get in."},
{t:"Dynamic link library",a:"DLL",d:"Endpoints & Systems",def:"A shared library that a program loads at runtime rather than containing itself. Which one gets loaded, and from where, is a whole class of vulnerability."},
{t:"Symbolic link",a:"Symlink",d:"Endpoints & Systems",def:"A file that points at another file. Where a program follows one without checking, an attacker can redirect it to a file they should not reach."},
{t:"Partition",a:"",d:"Endpoints & Systems",def:"A major division of a physical disk, treated as a separate volume by the operating system."},
{t:"Fast file system",a:"FFS",d:"Endpoints & Systems",def:"The first major redesign of the Unix file system, using inodes and better on-disk layout for speed. The ancestor of the file systems in use now."},
{t:"Static host table",a:"hosts file",d:"Endpoints & Systems",def:"A plain text file mapping names to addresses, consulted before DNS. Editing it is a simple and often overlooked redirection technique."},
{t:"Interrupt",a:"",d:"Endpoints & Systems",def:"A signal telling the operating system that something has happened and needs attention now."},
{t:"State machine",a:"",d:"Endpoints & Systems",def:"A system that moves through a defined series of conditions, one at a time. Protocols and parsers are state machines, and their bugs are usually states nobody planned for."},
{t:"Share",a:"",d:"Endpoints & Systems",def:"A directory or printer made available to other machines over the network."},
{t:"Unprotected share",a:"",d:"Endpoints & Systems",def:"A share anyone can connect to. Still one of the most common ways ransomware moves through an organisation."},
{t:"Legion",a:"",d:"Endpoints & Systems",def:"An old tool for finding unprotected network shares. The technique long outlived the tool."},
{t:"DumpSec",a:"",d:"Endpoints & Systems",def:"An old Windows auditing tool that dumped users, permissions, policies and services. Equally useful to an administrator and to an intruder."},
{t:"Registry (Windows)",a:"",d:"Endpoints & Systems",def:"The central store of Windows settings and configuration. Persistence, configuration and evidence all live here."},
{t:"Active content",a:"",d:"Endpoints & Systems",def:"Code embedded in a web page that runs on the visitor's machine when the page loads. The reason a page you merely opened can attack you."},
{t:"Applet",a:"",d:"Endpoints & Systems",def:"A small program delivered to run inside a browser, historically in Java. The model is gone; the lesson about running untrusted code is not."},
{t:"Browser",a:"",d:"Endpoints & Systems",def:"The client program that fetches and renders web content. Now the operating system most work actually happens in, and the most attacked software on any endpoint."},
{t:"Cookie",a:"",d:"Endpoints & Systems",def:"A small piece of data a server asks a browser to store and send back, so it can recognise the same client later. Session cookies are credentials in all but name."},
{t:"Hyperlink",a:"",d:"Endpoints & Systems",def:"A pointer in a document to something located elsewhere. The unit of the web, and the delivery mechanism for most phishing."},
{t:"HTML",a:"Hypertext Markup Language",d:"Endpoints & Systems",def:"The markup that describes a web page's structure and content."},
{t:"CGI",a:"Common Gateway Interface",d:"Endpoints & Systems",def:"The old mechanism for a web server to pass a request to an executable script and return its output. The first generation of dynamic web vulnerabilities lived here."},
{t:"Perl",a:"",d:"Endpoints & Systems",def:"A scripting language with strong text-processing roots, long the default for system administration and CGI scripts."},
{t:"Web server",a:"",d:"Endpoints & Systems",def:"The software that answers HTTP requests for content. Also the process most often running as the entry point to an internal network."},
{t:"World Wide Web",a:"WWW",d:"Endpoints & Systems",def:"The global collection of hypermedia documents and services reached over HTTP. Not a synonym for the internet, though everyone uses it as one."},
{t:"URI",a:"Uniform Resource Identifier",d:"Endpoints & Systems",def:"The general term for names and addresses that identify something on the web. A URL is a URI that also says where to get it."},
{t:"URL",a:"Uniform Resource Locator",d:"Endpoints & Systems",def:"The address of a resource: the protocol to use, then where the resource lives. The part users are asked to inspect and almost never do."},
{t:"Gnutella",a:"",d:"Endpoints & Systems",def:"An early peer-to-peer file sharing network where every client was also a server. An object lesson in how hard decentralised networks are to police."},
{t:"Finger",a:"",d:"Endpoints & Systems",def:"An old protocol that returned information about a user on a host. Helpful, informative and long since disabled for exactly that reason."},
{t:"Software",a:"",d:"Endpoints & Systems",def:"Programs and their associated data, stored in and executed by hardware, and changeable while running."},
{t:"Wired Equivalent Privacy",a:"WEP",d:"Endpoints & Systems",def:"The original Wi-Fi encryption standard, broken since the early 2000s. Finding it in use is finding an open network."},
{t:"Wireless Application Protocol",a:"WAP",d:"Endpoints & Systems",def:"An early specification for getting internet services onto mobile phones, before phones could simply speak the web."},
/* --- Application Security (added) --- */
{t:"Regression testing",a:"",d:"Application Security",def:"Running a fixed set of tests before each release to check that what worked still works. Fuzzing is its adversarial cousin."},
/* --- Intelligence & Investigations (added) --- */
{t:"Cyber investigation",a:"",d:"Intelligence & Investigations",def:"Establishing what happened on a system, who did it and what can be proved about it. Distinct from incident response, which is about stopping it: an investigation has to survive scrutiny afterwards."},
{t:"Cybercrime",a:"",d:"Intelligence & Investigations",def:"Crime committed using a computer, or against one. The distinction matters in law: cyber as the means of an ordinary crime is charged differently from cyber as the target."},
{t:"Cyber-enabled vs cyber-dependent crime",a:"",d:"Intelligence & Investigations",def:"Cyber-enabled crime is an old crime committed with new tools — fraud, extortion, harassment. Cyber-dependent crime could not exist without computers — intrusion, malware, denial of service."},
{t:"Cyber intelligence",a:"",d:"Intelligence & Investigations",def:"Collecting and analysing information about adversaries in cyberspace to inform decisions, rather than to prosecute. Different standard of proof, different consumers, different timelines from an investigation."},
{t:"Public vs private sector response",a:"",d:"Intelligence & Investigations",def:"Government investigates to enforce law and protect the state; a company investigates to stop the bleeding, meet its obligations and protect its business. The same incident produces two different investigations with different definitions of success."},
{t:"Criticality",a:"",d:"Intelligence & Investigations",def:"How much a given failure actually matters — which is judged very differently by a government protecting a country and a company protecting a balance sheet. It is why the same vulnerability gets very different responses."},
{t:"Attribution threshold",a:"",d:"Intelligence & Investigations",def:"Establishing who was behind an intrusion, to a standard someone will act on. Technical indicators rarely get there alone; attribution usually needs intelligence, finance and human sources too."},
{t:"Cyber warfare",a:"",d:"Intelligence & Investigations",def:"The use of cyber operations as an instrument of armed conflict. High impact for low cost, which is precisely what makes proportional response so contested."},
{t:"Proportional response",a:"",d:"Intelligence & Investigations",def:"The principle that retaliation should match the force used against you. Applied to cyber operations it is genuinely unsettled: what a proportional answer to a destructive intrusion looks like is still argued over."},
{t:"Hybrid warfare",a:"",d:"Intelligence & Investigations",def:"Combining cyber operations, information operations, economic pressure and conventional force. The Sandworm attacks on Ukraine are the standing example."},
{t:"CISA",a:"Cybersecurity and Infrastructure Security Agency",d:"Intelligence & Investigations",def:"The US civilian agency responsible for defending federal networks and helping critical infrastructure defend itself. It advises and coordinates; it does not investigate crimes."},
{t:"FBI",a:"Federal Bureau of Investigation",d:"Intelligence & Investigations",def:"The lead US federal agency for investigating cybercrime, and simultaneously a domestic intelligence service. It works cases for prosecution and collects intelligence, which is an unusual combination."},
{t:"CIA",a:"Central Intelligence Agency",d:"Intelligence & Investigations",def:"The US foreign intelligence service, collecting abroad through its own operations and through partners. It has no domestic law-enforcement role."},
{t:"NSA",a:"National Security Agency",d:"Intelligence & Investigations",def:"The US signals intelligence agency — interception, cryptanalysis, satellites — and also the source of much defensive cryptographic guidance. Long nicknamed 'no such agency' for how little it acknowledged itself."},
{t:"US Cyber Command",a:"USCYBERCOM",d:"Intelligence & Investigations",def:"The US military command for cyber operations, defensive and offensive. Where CISA protects and the FBI investigates, this is the element that can act against an adversary."},
{t:"Department of Homeland Security",a:"DHS",d:"Intelligence & Investigations",def:"The US department that CISA and the Secret Service sit under, covering domestic protective security across borders, infrastructure and emergencies."},
{t:"Department of Justice",a:"DOJ",d:"Intelligence & Investigations",def:"The US department that prosecutes federal crime, including computer crime, and supervises the FBI. Its independence from political direction is a norm rather than a mechanism."},
{t:"US Secret Service",a:"USSS",d:"Intelligence & Investigations",def:"Originally the investigators of counterfeit currency, now a principal US agency for financial cybercrime — payment card fraud, cryptocurrency laundering, digital financial investigations — alongside its protective mission."},
{t:"Department of Defense intelligence",a:"DoD",d:"Intelligence & Investigations",def:"The military side of US intelligence, including the service intelligence organisations such as naval intelligence. The US intelligence community runs to some eighteen to twenty separate organisations."},
{t:"InfraGard",a:"",d:"Intelligence & Investigations",def:"The FBI's partnership programme with the private sector, sharing threat information with the operators of critical infrastructure across financial, energy, health and other sectors."},
{t:"Southern District of New York",a:"SDNY",d:"Intelligence & Investigations",def:"The federal prosecutorial district that handles a disproportionate share of US financial and white-collar cases, cyber fraud included. Where a case is charged shapes how it is investigated."},
{t:"MI5",a:"Security Service",d:"Intelligence & Investigations",def:"The United Kingdom's domestic security service, responsible for threats inside the UK — terrorism, espionage, subversion."},
{t:"MI6",a:"Secret Intelligence Service, SIS",d:"Intelligence & Investigations",def:"The United Kingdom's foreign intelligence service, collecting abroad. The James Bond half of the pair; MI5 is the domestic half."},
{t:"GCHQ",a:"Government Communications Headquarters",d:"Intelligence & Investigations",def:"The UK signals intelligence agency, and the parent of the National Cyber Security Centre."},
{t:"National Crime Agency",a:"NCA",d:"Intelligence & Investigations",def:"The UK's national law enforcement agency for serious and organised crime, including its National Cyber Crime Unit."},
{t:"Scotland Yard",a:"Metropolitan Police",d:"Intelligence & Investigations",def:"The headquarters of London's police force, and by extension shorthand for British policing. A local force, not a national one — a common source of confusion in cross-border cases."},
{t:"INTERPOL",a:"International Criminal Police Organization",d:"Intelligence & Investigations",def:"The body that lets police forces in nearly two hundred countries pass information and requests to each other. It coordinates and notifies; it has no officers who make arrests."},
{t:"Europol",a:"",d:"Intelligence & Investigations",def:"The European Union's law enforcement agency, supporting member states on transnational crime and running the European Cybercrime Centre."},
{t:"Five Eyes",a:"FVEY",d:"Intelligence & Investigations",def:"The intelligence-sharing arrangement between the United States, United Kingdom, Canada, Australia and New Zealand. The deepest such arrangement that exists between states."},
{t:"NATO",a:"North Atlantic Treaty Organization",d:"Intelligence & Investigations",def:"The intergovernmental military alliance of North American and European states. It has said that a cyber attack can trigger the collective defence commitment, without saying which one would."},
{t:"NATO CCDCOE",a:"Cooperative Cyber Defence Centre of Excellence",d:"Intelligence & Investigations",def:"NATO's cyber defence research and training centre in Tallinn, best known for the Tallinn Manual on how international law applies to cyber operations."},
{t:"ENISA",a:"European Union Agency for Cybersecurity",d:"Intelligence & Investigations",def:"The EU's cybersecurity agency, which produces guidance, threat analysis and certification schemes rather than investigating incidents."},
{t:"United Nations (cyber norms)",a:"UN",d:"Intelligence & Investigations",def:"The forum where states negotiate norms for behaviour in cyberspace. It produces recommendations, not enforcement, which is both its limit and the reason states will talk there."},
{t:"Royal Canadian Mounted Police",a:"RCMP",d:"Intelligence & Investigations",def:"Canada's national police force, and its point of contact for cross-border cybercrime investigations."},
{t:"Australian Federal Police",a:"AFP",d:"Intelligence & Investigations",def:"Australia's national police force, handling cybercrime with national or international reach."},
{t:"Mutual legal assistance treaty",a:"MLAT",d:"Intelligence & Investigations",def:"The formal channel by which one country asks another for evidence. Slow enough — often months — that investigators plan around it rather than through it."},
{t:"Extradition",a:"",d:"Intelligence & Investigations",def:"Handing a suspect over to another country to be prosecuted. It requires a treaty and a matching offence, which is why suspects in some countries are effectively unreachable."},
{t:"Budapest Convention",a:"Convention on Cybercrime",d:"Intelligence & Investigations",def:"The Council of Europe treaty that harmonises cybercrime offences and cooperation procedures across its parties. The closest thing to a common international framework."},
{t:"Subpoena",a:"",d:"Intelligence & Investigations",def:"A legal order compelling someone to produce records or testimony. In practice it gets subscriber and transactional detail — account records, IP addresses, connection logs — not the content of communications."},
{t:"Search warrant",a:"",d:"Intelligence & Investigations",def:"A judicial authorisation to search and seize, granted on probable cause. It is what reaches content: the messages themselves, the files, the contents of an account."},
{t:"Metadata vs content",a:"",d:"Intelligence & Investigations",def:"Metadata is the record about a communication — who, when, from where, how long. Content is what was said. They are protected differently in law, and metadata is very often enough on its own."},
{t:"Preservation request",a:"",d:"Intelligence & Investigations",def:"An order telling a provider to freeze an account's data while legal process is prepared. Without it, logs age out before the warrant arrives."},
{t:"Court order",a:"",d:"Intelligence & Investigations",def:"An intermediate legal instrument between a subpoena and a warrant, reaching records a subpoena cannot but stopping short of content."},
{t:"No expectation of privacy",a:"",d:"Intelligence & Investigations",def:"The doctrine that where a person had no reasonable expectation of privacy, evidence can be gathered without a warrant. Corporate banners and acceptable use policies exist largely to establish it."},
{t:"Digital evidence",a:"",d:"Intelligence & Investigations",def:"Data used to prove or disprove something in a proceeding. It must be collected in a way that keeps it authentic, complete and demonstrably unaltered."},
{t:"Computer forensics",a:"",d:"Intelligence & Investigations",def:"Recovering and analysing data from computers to a standard that will stand up in court. Method and documentation matter as much as findings."},
{t:"Embedded forensics",a:"",d:"Intelligence & Investigations",def:"Forensics on devices that are not general-purpose computers — vehicles, controllers, medical devices, IoT. The data is there; the tooling to get at it usually is not."},
{t:"Drone forensics",a:"",d:"Intelligence & Investigations",def:"Recovering flight logs, telemetry, imagery and controller pairings from unmanned aircraft. Increasingly routine in both criminal and security investigations."},
{t:"Volatile vs non-volatile storage",a:"",d:"Intelligence & Investigations",def:"Volatile memory disappears when power is cut; disks survive. It sets the order of collection: capture memory first, then image the disk."},
{t:"Joint investigation",a:"",d:"Intelligence & Investigations",def:"An investigation run by more than one agency, often across borders. It multiplies reach and multiplies the questions of who charges, where, and under whose rules."},
{t:"Cross-border investigation",a:"",d:"Intelligence & Investigations",def:"An investigation where evidence, suspects and victims sit in different jurisdictions. The technical work is usually the easy part."},
{t:"International warrant",a:"",d:"Intelligence & Investigations",def:"A request through international channels for the arrest or search of someone abroad. Its force depends entirely on the receiving country's cooperation."},
{t:"IP lookup",a:"",d:"Intelligence & Investigations",def:"Finding out what is known about an address — who holds it, which network and country it sits in. The first step of most attributions, and the least conclusive."},
{t:"Proxy (investigative view)",a:"",d:"Intelligence & Investigations",def:"An intermediate server that stands between the user and the destination, so the destination sees the proxy's address. It moves the question of identity one hop back."},
{t:"VPN (investigative view)",a:"",d:"Intelligence & Investigations",def:"An encrypted tunnel to a provider that then makes connections on the user's behalf. Whether it defeats an investigation depends entirely on what logs the provider keeps."},
{t:"Node (Tor)",a:"Relay",d:"Intelligence & Investigations",def:"One of the volunteer machines a Tor circuit is built from. Each relay knows only the hop before and the hop after, which is what breaks the link between sender and destination."},
{t:"Silk Road",a:"",d:"Intelligence & Investigations",def:"The Tor-hosted drug marketplace taken down in 2013. The standing case study in dark web investigation: the site was anonymous, and the operator's early forum posts and cash-out were not."},
{t:"Cash-out",a:"Off-ramp",d:"Intelligence & Investigations",def:"The point where criminal proceeds are converted into usable money. Cryptocurrency is traceable on the chain, so the exchange where it is cashed out is where investigations most often land."},
{t:"Crime of opportunity",a:"",d:"Intelligence & Investigations",def:"An offence committed because the chance appeared, not because it was planned. Most low-level cybercrime, and the reason basic hygiene removes so much of it."},
{t:"Remote work scam",a:"",d:"Intelligence & Investigations",def:"Fraud built on remote employment — fake workers, bought identities, remote access software installed on company machines. The employment process becomes the intrusion vector."},
{t:"Insider threat vs cyber",a:"",d:"Intelligence & Investigations",def:"Harm from someone with legitimate access. Whether it counts as cyber or physical depends on how they took the data, not on the harm — which is why insider programmes sit across both."},
{t:"1999 Brooklyn credit card case",a:"",d:"Intelligence & Investigations",def:"An early US case where stolen card details were used at scale — investigated as identity theft rather than as hacking. An illustration of how cyber cases get charged under whatever law already exists."},
/* --- Classification & Personal Data (added) --- */
{t:"Classification scheme",a:"",d:"Classification & Personal Data",def:"Sorting information into levels according to the harm its disclosure would cause, so protection can follow the label rather than being argued case by case."},
{t:"Public (classification)",a:"",d:"Classification & Personal Data",def:"Information intended for anyone — published material, marketing, public filings. The only class that needs no protection against disclosure, though it still needs integrity."},
{t:"Internal (classification)",a:"",d:"Classification & Personal Data",def:"Information meant to stay inside the organisation but not damaging if it leaked — internal directories, process documents, ordinary email. The default class most data falls into."},
{t:"Confidential (classification)",a:"",d:"Classification & Personal Data",def:"Information whose disclosure would harm the organisation or a person: contracts, salaries, customer lists, unreleased results. Access is granted by need, not by seniority."},
{t:"Restricted (classification)",a:"Highly confidential",d:"Classification & Personal Data",def:"The most sensitive commercial class: credentials, encryption keys, merger plans, source code, regulated personal data. Small named access lists and logged access."},
{t:"Sensitive information (commercial)",a:"",d:"Classification & Personal Data",def:"The working middle of a private-sector scheme — information that is not secret but should not circulate freely. The label does the work; the definitions vary by organisation."},
{t:"Classification levels (government)",a:"",d:"Classification & Personal Data",def:"The US government scheme: Unclassified, then Confidential, Secret and Top Secret, according to the damage disclosure would cause. Compartments and handling caveats sit on top of the level."},
{t:"Top Secret",a:"TS",d:"Classification & Personal Data",def:"The US classification for information whose disclosure would be expected to cause exceptionally grave damage to national security."},
{t:"Secret",a:"",d:"Classification & Personal Data",def:"The US classification for information whose disclosure would cause serious damage to national security."},
{t:"Confidential (government)",a:"",d:"Classification & Personal Data",def:"The lowest US classification level, for information whose disclosure would cause damage to national security. Not the same thing as commercial confidential."},
{t:"Unclassified",a:"U",d:"Classification & Personal Data",def:"Government information with no classification level. It may still be controlled: CUI — controlled unclassified information — is unclassified but restricted."},
{t:"Security clearance",a:"",d:"Classification & Personal Data",def:"A vetting decision that a person may be trusted with classified information up to a level. Clearance alone is not enough: access also requires need to know."},
{t:"Need to know",a:"",d:"Classification & Personal Data",def:"The rule that clearance permits access only to the specific information required for your role. It is what stops a Top Secret clearance from being a key to everything."},
{t:"Compartmentalisation",a:"",d:"Classification & Personal Data",def:"Splitting classified information into compartments so that access to one grants nothing in another. It limits the damage a single insider can do."},
{t:"Personally identifiable information",a:"PII",d:"Classification & Personal Data",def:"Information that identifies a specific person, alone or combined with other data. Direct identifiers: name, Social Security number, passport or driving licence number, email address, phone number, home address, account numbers, biometric templates, face photograph, device or vehicle identifiers. Indirect ones become identifying in combination — date of birth with postcode with gender is famously enough to single out most people."},
{t:"Sensitive PII",a:"",d:"Classification & Personal Data",def:"The subset of personal data whose exposure causes immediate, serious harm: Social Security and national ID numbers, financial account and card numbers, passport and driving licence numbers, biometrics, and credentials. Usually the trigger for breach notification and for encryption requirements."},
{t:"Protected health information",a:"PHI",d:"Classification & Personal Data",def:"Health information tied to an identifiable person and handled by a covered organisation — diagnoses, treatment records, prescriptions, test results, insurance and billing detail, appointment records, provider notes. Under HIPAA it is the identifiers plus the health context that make it PHI."},
{t:"HIPAA identifiers",a:"Safe harbour list",d:"Classification & Personal Data",def:"The eighteen identifiers that must be stripped for health data to count as de-identified: names, geography finer than a state, all dates tied to an individual, phone and fax numbers, email, Social Security, medical record, health plan, account, licence and vehicle numbers, device identifiers, URLs, IP addresses, biometrics, full-face photographs, and any other unique code."},
{t:"Personal information",a:"PI",d:"Classification & Personal Data",def:"The broader legal category used in privacy law — anything relating to an identified or identifiable person, including data that never names them: IP addresses, cookie and advertising identifiers, location traces, browsing history, inferences drawn about them. Wider than PII by design."},
{t:"GDPR special categories",a:"Sensitive personal data",d:"Classification & Personal Data",def:"Under GDPR: racial or ethnic origin, political opinions, religious or philosophical beliefs, trade union membership, genetic data, biometric data used to identify someone, health data, and data about sex life or sexual orientation. Processing it needs a specific additional condition, not just a lawful basis."},
{t:"Payment card data",a:"CHD",d:"Classification & Personal Data",def:"The cardholder data PCI DSS governs — the card number, cardholder name, expiry and service code — plus the authentication data that may never be stored at all: the full magnetic stripe, the CVV, and the PIN."},
{t:"Controlled unclassified information",a:"CUI",d:"Classification & Personal Data",def:"US government information that is unclassified but still restricted in how it is handled, covering categories such as export-controlled, law enforcement and privacy data. NIST SP 800-171 sets what contractors must do to protect it."},
{t:"Trade secret",a:"",d:"Classification & Personal Data",def:"Commercially valuable information that derives its value from being secret and that the holder takes reasonable steps to keep secret. The reasonable steps are a legal requirement, not just good practice."},
{t:"Attorney-client privileged material",a:"",d:"Classification & Personal Data",def:"Legal advice and communications with counsel, protected from disclosure. Incident investigations are often run under privilege, which changes who may see the findings and how they are written."},
{t:"De-identification",a:"",d:"Classification & Personal Data",def:"Removing identifiers so data no longer points to a person. It is a spectrum, not a switch: weakly de-identified data is routinely re-identified by linking it to something else."},
{t:"Data handling rules",a:"",d:"Classification & Personal Data",def:"What each classification actually requires in practice — who may access it, how it is stored and transmitted, whether it may leave the country or the device, how it is disposed of. A classification without handling rules is decoration."},
{t:"Labelling",a:"Marking",d:"Classification & Personal Data",def:"Recording the classification on the document, file or message itself so the handling rules travel with it. Automated labelling is what makes DLP enforceable."},
{t:"Notification letter",a:"Breach notice",d:"Classification & Personal Data",def:"The letter sent to people whose personal data was exposed, saying what happened and what is being offered. In most US states and under GDPR it is a legal duty with a clock attached."},
/* --- dark web and marketplace investigation (added) --- */
{t:"Deep web",a:"",d:"Networking & Protocols",def:"Everything on the web that a search engine has not indexed — anything behind a login, a paywall or a form. Vastly bigger than the dark web, and routinely confused with it: your bank statements are deep web, not dark web."},
{t:"Hidden service",a:".onion address",d:"Networking & Protocols",def:"A server reachable only inside Tor, addressed by a cryptographic name ending in .onion rather than a domain. Neither side of the connection learns the other's IP, which is why takedowns target operators rather than addresses."},
{t:"Dark web marketplace",a:"",d:"Intelligence & Investigations",def:"A hidden service selling illicit goods, run with escrow, vendor ratings and dispute handling like any other marketplace. They are seized regularly and reconstitute under new names within weeks."},
{t:"Dark web archive",a:"Marketplace archive",d:"Intelligence & Investigations",def:"Preserved copies of seized or defunct hidden services — page captures, listings, vendor profiles and forum threads — held by researchers and law enforcement. The Silk Road archives are the worked example: the site is gone, and years of its listings, PGP keys and forum posts remain searchable evidence."},
{t:"Operational security failure",a:"OPSEC failure",d:"Intelligence & Investigations",def:"The mistake that undoes an otherwise anonymous operation — a reused username, an early forum post, a personal email in a code commit, a package addressed to a real name. Silk Road's operator was found through his own early advertising posts, not through breaking Tor."},
{t:"Exit scam",a:"",d:"Intelligence & Investigations",def:"A marketplace operator shutting down and keeping whatever is held in escrow. It ends more dark web markets than police action does."},
{t:"Blockchain analysis",a:"Chain analysis",d:"Intelligence & Investigations",def:"Following cryptocurrency through the public ledger, clustering addresses and linking them to real identities at the points where coins meet a regulated exchange. The reason a public ledger is worse for criminals than cash."},
{t:"Tumbler",a:"Mixer",d:"Intelligence & Investigations",def:"A service that pools and re-splits cryptocurrency to break the link between source and destination. Using one is itself a signal, and several operators have been prosecuted."},
{t:"Undercover purchase",a:"Test buy",d:"Intelligence & Investigations",def:"Buying from a marketplace vendor to establish what is being sold, from whom, and where it ships from. It converts an anonymous listing into physical evidence and a delivery address."},
{t:"Takedown",a:"Seizure notice",d:"Intelligence & Investigations",def:"Seizing the infrastructure behind a criminal service and, usually, replacing its front page with a law enforcement banner. Effective as disruption and as messaging; rarely permanent on its own."},
/* --- jumping between hosts (added) --- */
{t:"Jumping",a:"Hopping",d:"Networking & Protocols",def:"Moving a connection through a chain of intermediate machines so the far end never sees where it started. It is what Tor does deliberately with relays, and what an attacker does through compromised hosts — each hop is one more party who would have to be asked, in one more jurisdiction, to trace the traffic back."},
{t:"Circuit",a:"Tor circuit",d:"Networking & Protocols",def:"The path of relays Tor picks for your traffic — normally three, rebuilt every few minutes. No single relay in it knows both who you are and where you are going."},
{t:"Proxy chain",a:"Chained proxies",d:"Networking & Protocols",def:"Stringing several proxies together so each one only knows its neighbours. Cheap to set up, and only as private as the least trustworthy link, which keeps logs."},
{t:"Pivoting",a:"",d:"Attacks & Exploitation",def:"Using a machine you have already compromised as the launch point for reaching further into a network. The second host is attacked from inside, where the firewall is not looking."},
{t:"Island hopping",a:"",d:"Attacks & Exploitation",def:"Attacking an organisation by first compromising a smaller partner, supplier or subsidiary that is trusted by it. The way into the bank is often through the firm that cleans its offices' laptops."},
{t:"VLAN hopping",a:"",d:"Attacks & Exploitation",def:"Escaping the VLAN you were put on to reach traffic on another, usually by abusing trunk negotiation or double-tagged frames. It is why VLANs are a segmentation convenience, not a security boundary."}
];
